import type { Soru } from "../sorular";

export const P12: Soru[] = [
  { id: "p12-001", k: "Bilim", s: "Altının kimyasal sembolü nedir?", d: "Au", y: ["Ag", "Al"], a: "Au, altının Latince adı \"aurum\"dan gelir. Ag gümüşün, Al alüminyumun sembolüdür." },
  { id: "p12-002", k: "Bilim", s: "Gümüşün kimyasal sembolü nedir?", d: "Ag", y: ["Au", "Gm"], a: "Ag, gümüşün Latince adı \"argentum\"dan gelir." },
  { id: "p12-003", k: "Bilim", s: "Demirin kimyasal sembolü nedir?", d: "Fe", y: ["De", "Ir"], a: "Fe, demirin Latince adı \"ferrum\"dan gelir." },
  { id: "p12-004", k: "Bilim", s: "Sodyumun kimyasal sembolü nedir?", d: "Na", y: ["So", "Sd"], a: "Na, sodyumun Latince adı \"natrium\"dan gelir." },
  { id: "p12-005", k: "Bilim", s: "Potasyumun kimyasal sembolü nedir?", d: "K", y: ["P", "Po"], a: "K, potasyumun Latince adı \"kalium\"dan gelir. P fosforun, Po polonyumun sembolüdür." },
  { id: "p12-006", k: "Bilim", s: "Kurşunun kimyasal sembolü nedir?", d: "Pb", y: ["Ld", "Kr"], a: "Pb, kurşunun Latince adı \"plumbum\"dan gelir. Kr ise soy gaz kriptonun sembolüdür." },
  { id: "p12-007", k: "Bilim", s: "Cıvanın kimyasal sembolü nedir?", d: "Hg", y: ["Cv", "Me"], a: "Hg, Yunanca kökenli \"hydrargyrum\" yani \"sıvı gümüş\" adından gelir." },
  { id: "p12-008", k: "Bilim", s: "Bakırın kimyasal sembolü nedir?", d: "Cu", y: ["Ba", "Bk"], a: "Cu, bakırın Latince adı \"cuprum\"dan gelir. Ba baryumun sembolüdür." },
  { id: "p12-009", k: "Bilim", s: "Kalayın kimyasal sembolü nedir?", d: "Sn", y: ["Ka", "Ti"], a: "Sn, kalayın Latince adı \"stannum\"dan gelir. Ti titanyumun sembolüdür." },
  { id: "p12-010", k: "Bilim", s: "Azotun kimyasal sembolü nedir?", d: "N", y: ["A", "Az"], a: "Azot, uluslararası adıyla nitrojendir ve sembolü N'dir." },
  { id: "p12-011", k: "Bilim", s: "Hidrojenin atom numarası kaçtır?", d: "1", y: ["2", "0"], a: "Hidrojenin çekirdeğinde tek proton vardır, bu yüzden periyodik tablonun ilk elementidir." },
  { id: "p12-012", k: "Bilim", s: "Helyumun atom numarası kaçtır?", d: "2", y: ["4", "1"], a: "Helyumun 2 protonu vardır. 4 ise en yaygın helyum izotopunun kütle numarasıdır." },
  { id: "p12-013", k: "Bilim", s: "Karbonun atom numarası kaçtır?", d: "6", y: ["12", "8"], a: "Karbonun 6 protonu vardır. 12, en yaygın karbon izotopunun kütle numarasıdır." },
  { id: "p12-014", k: "Bilim", s: "Oksijenin atom numarası kaçtır?", d: "8", y: ["16", "6"], a: "Oksijenin 8 protonu vardır. En yaygın izotopu oksijen-16'dır." },
  { id: "p12-015", k: "Bilim", s: "Azotun atom numarası kaçtır?", d: "7", y: ["14", "5"], a: "Azotun 7 protonu vardır. En yaygın izotopu azot-14'tür." },
  { id: "p12-016", k: "Bilim", s: "Demirin atom numarası kaçtır?", d: "26", y: ["56", "28"], a: "Demirin 26 protonu vardır. 56, en yaygın demir izotopunun kütle numarasıdır." },
  { id: "p12-017", k: "Bilim", s: "Altının atom numarası kaçtır?", d: "79", y: ["47", "82"], a: "Altının 79 protonu vardır. 47 gümüşün, 82 kurşunun atom numarasıdır." },
  { id: "p12-018", k: "Bilim", s: "Uranyumun atom numarası kaçtır?", d: "92", y: ["94", "88"], a: "Uranyumun 92 protonu vardır. Doğada kayda değer miktarda bulunan en ağır elementtir." },
  { id: "p12-019", k: "Bilim", s: "Periyodik tabloyu 1869'da yayımlayan Rus kimyager kimdir?", d: "Dmitri Mendeleyev", y: ["Antoine Lavoisier", "John Dalton"], a: "Mendeleyev tablosunda boşluklar bırakmış ve henüz bulunmamış bazı elementlerin özelliklerini önceden tahmin etmişti." },
  { id: "p12-020", k: "Bilim", s: "Modern periyodik tabloda elementler neye göre sıralanır?", d: "Atom numarasına", y: ["Keşif tarihine", "Yoğunluğa"], a: "Bugünkü tablo proton sayısına, yani atom numarasına göre düzenlenir. Mendeleyev ise atom kütlesini esas almıştı." },
  { id: "p12-022", k: "Bilim", s: "Periyodik tablodaki dikey sütunlara ne ad verilir?", d: "Grup", y: ["Periyot", "Sıra"], a: "Aynı gruptaki elementlerin dış kabuk elektron düzeni benzerdir, bu yüzden kimyasal özellikleri de benzer." },
  { id: "p12-023", k: "Bilim", s: "Periyodik tablodaki yatay satırlara ne ad verilir?", d: "Periyot", y: ["Grup", "Sütun"], a: "Tabloda 7 periyot vardır. Periyot numarası, atomun elektron kabuğu sayısını gösterir." },
  { id: "p12-024", k: "Bilim", s: "Periyodik tablonun 18. grubundaki elementlere ne denir?", d: "Soy gazlar", y: ["Halojenler", "Alkali metaller"], a: "Helyum, neon, argon, kripton, ksenon ve radon soy gazlardır. Tepkimeye girmeye pek yatkın değildirler." },
  { id: "p12-025", k: "Bilim", s: "Flor, klor, brom ve iyotun bulunduğu 17. gruba ne denir?", d: "Halojenler", y: ["Soy gazlar", "Geçiş metalleri"], a: "Halojen, Yunanca \"tuz yapan\" anlamına gelir. Bu elementler metallerle kolayca tuz oluşturur." },
  { id: "p12-026", k: "Bilim", s: "Lityum, sodyum ve potasyumun bulunduğu 1. grup metallerine ne denir?", d: "Alkali metaller", y: ["Toprak alkali metaller", "Geçiş metalleri"], a: "Alkali metaller yumuşaktır ve suyla şiddetli tepkimeye girer. Hidrojen 1. grupta yer alsa da alkali metal sayılmaz." },
  { id: "p12-027", k: "Bilim", s: "Magnezyum ve kalsiyumun bulunduğu 2. gruba ne denir?", d: "Toprak alkali metaller", y: ["Alkali metaller", "Halojenler"], a: "Berilyum, magnezyum, kalsiyum, stronsiyum, baryum ve radyum toprak alkali metallerdir." },
  { id: "p12-028", k: "Bilim", s: "Oda sıcaklığında sıvı halde bulunan metal hangisidir?", d: "Cıva", y: ["Kurşun", "Kalay"], a: "Cıva -39 °C civarında donar, bu yüzden oda sıcaklığında sıvıdır. Eskiden termometrelerde kullanılırdı." },
  { id: "p12-029", k: "Bilim", s: "Oda sıcaklığında sıvı halde bulunan ametal hangisidir?", d: "Brom", y: ["İyot", "Klor"], a: "Brom koyu kırmızı-kahverengi bir sıvıdır. Klor gaz, iyot ise katıdır." },
  { id: "p12-030", k: "Bilim", s: "En hafif element hangisidir?", d: "Hidrojen", y: ["Helyum", "Lityum"], a: "Hidrojen atomu tek proton ve tek elektrondan oluşur. Atom kütlesi en düşük elementtir." },
  { id: "p12-031", k: "Bilim", s: "Evrende en bol bulunan element hangisidir?", d: "Hidrojen", y: ["Helyum", "Oksijen"], a: "Evrendeki sıradan maddenin kütlece yaklaşık dörtte üçü hidrojendir. İkinci sırada helyum gelir." },
  { id: "p12-035", k: "Bilim", s: "Kuru havada yaklaşık %0,9 oranıyla üçüncü sırada olan gaz hangisidir?", d: "Argon", y: ["Karbondioksit", "Neon"], a: "Argon, azot ve oksijenden sonra havada en bol bulunan gazdır. Karbondioksit oranı bunun çok altındadır." },
  { id: "p12-036", k: "Bilim", s: "Elmas ve grafit hangi elementten oluşur?", d: "Karbon", y: ["Silisyum", "Bor"], a: "İkisi de saf karbondur. Farkı, karbon atomlarının dizilişinden gelir." },
  { id: "p12-037", k: "Bilim", s: "Kalsiyumun kimyasal sembolü nedir?", d: "Ca", y: ["K", "Cl"], a: "Kalsiyumun sembolü Ca'dır. K potasyumun, Cl klorun sembolüdür." },
  { id: "p12-038", k: "Bilim", s: "Klorun kimyasal sembolü nedir?", d: "Cl", y: ["C", "Kl"], a: "Klorun sembolü Cl'dir. Tek başına C ise karbonun sembolüdür." },
  { id: "p12-039", k: "Bilim", s: "Fosforun kimyasal sembolü nedir?", d: "P", y: ["F", "Fs"], a: "Fosforun sembolü P'dir. F ise florun sembolüdür." },
  { id: "p12-040", k: "Bilim", s: "Florun kimyasal sembolü nedir?", d: "F", y: ["Fl", "Fr"], a: "Florun sembolü F'dir. Fr fransiyumun, Fl ise flerovyumun sembolüdür." },
  { id: "p12-041", k: "Bilim", s: "Kükürdün kimyasal sembolü nedir?", d: "S", y: ["K", "Su"], a: "Kükürdün sembolü S'dir, Latince adı \"sulfur\"dan gelir." },
  { id: "p12-042", k: "Bilim", s: "Magnezyumun kimyasal sembolü nedir?", d: "Mg", y: ["Mn", "Ma"], a: "Magnezyumun sembolü Mg'dir. Mn ise manganın sembolüdür; ikisi sık karıştırılır." },
  { id: "p12-043", k: "Bilim", s: "Tungstenin kimyasal sembolü nedir?", d: "W", y: ["Tu", "Tg"], a: "W, tungstenin diğer adı olan \"wolfram\"dan gelir." },
  { id: "p12-044", k: "Bilim", s: "Antimonun kimyasal sembolü nedir?", d: "Sb", y: ["An", "At"], a: "Sb, antimonun Latince adı \"stibium\"dan gelir. At ise astatinin sembolüdür." },
  { id: "p12-045", k: "Bilim", s: "Silisyumun kimyasal sembolü nedir?", d: "Si", y: ["S", "Sl"], a: "Silisyumun sembolü Si'dir. Kum ve camın ana bileşeni olan silisyum dioksitte bulunur." },
  { id: "p12-046", k: "Bilim", s: "Çinkonun kimyasal sembolü nedir?", d: "Zn", y: ["Ci", "Zi"], a: "Çinkonun sembolü Zn'dir, Almanca \"Zink\" adından gelir." },
  { id: "p12-047", k: "Bilim", s: "Platinin kimyasal sembolü nedir?", d: "Pt", y: ["Pl", "Pa"], a: "Platinin sembolü Pt'dir. Pa ise protaktinyumun sembolüdür." },
  { id: "p12-048", k: "Bilim", s: "Borun kimyasal sembolü nedir?", d: "B", y: ["Bo", "Br"], a: "Borun sembolü B'dir. Br bromun sembolüdür. Türkiye dünyanın en büyük bor rezervlerine sahiptir." },
  { id: "p12-049", k: "Bilim", s: "İyotun kimyasal sembolü nedir?", d: "I", y: ["Io", "Y"], a: "İyotun sembolü I'dır. Y ise itriyum elementinin sembolüdür." },
  { id: "p12-050", k: "Bilim", s: "Kromun kimyasal sembolü nedir?", d: "Cr", y: ["Kr", "Ch"], a: "Kromun sembolü Cr'dir. Kr, soy gaz kriptonun sembolüdür." },
  { id: "p12-051", k: "Bilim", s: "Kobaltın kimyasal sembolü nedir?", d: "Co", y: ["Ko", "Cb"], a: "Kobaltın sembolü Co'dur. Dikkat: CO yazılırsa karbonmonoksit anlamına gelir." },
  { id: "p12-052", k: "Bilim", s: "Polonyum elementi adını hangi ülkeden alır?", d: "Polonya", y: ["Portekiz", "Fransa"], a: "Marie Curie, keşfettiği elemente doğduğu ülke Polonya'nın adını vermiştir." },
  { id: "p12-053", k: "Bilim", s: "Germanyum elementi adını hangi ülkeden alır?", d: "Almanya", y: ["Fransa", "İsveç"], a: "Germanyumu 1886'da Alman kimyager Clemens Winkler bulmuş ve Almanya'nın Latince adı Germania'dan adlandırmıştır." },
  { id: "p12-054", k: "Bilim", s: "Helyum adını hangi gök cisminden alır?", d: "Güneş", y: ["Ay", "Jüpiter"], a: "Helyum ilk kez Güneş'in tayfında fark edildi. Adı Yunanca güneş anlamına gelen \"helios\"tan gelir." },
  { id: "p12-055", k: "Bilim", s: "Lityumun atom numarası kaçtır?", d: "3", y: ["4", "2"], a: "Lityumun 3 protonu vardır. En hafif metaldir ve pillerde yaygın olarak kullanılır." },
  { id: "p12-056", k: "Bilim", s: "Neonun atom numarası kaçtır?", d: "10", y: ["8", "18"], a: "Neonun 10 protonu vardır. 18 ise argonun atom numarasıdır." },
  { id: "p12-057", k: "Bilim", s: "Sodyumun atom numarası kaçtır?", d: "11", y: ["12", "19"], a: "Sodyumun 11 protonu vardır. 12 magnezyumun, 19 potasyumun atom numarasıdır." },
  { id: "p12-058", k: "Bilim", s: "Klorun atom numarası kaçtır?", d: "17", y: ["35", "16"], a: "Klorun 17 protonu vardır. 35 ise en yaygın klor izotopunun kütle numarasıdır." },
  { id: "p12-059", k: "Bilim", s: "Atom çekirdeğinde hangi parçacıklar bulunur?", d: "Proton ve nötron", y: ["Proton ve elektron", "Elektron ve nötron"], a: "Proton ve nötron çekirdekte, elektronlar ise çekirdeğin çevresinde bulunur." },
  { id: "p12-060", k: "Bilim", s: "Elektronun elektrik yükü nasıldır?", d: "Negatif", y: ["Pozitif", "Yüksüz"], a: "Elektron negatif, proton pozitif yüklüdür. Nötron ise yüksüzdür." },
  { id: "p12-062", k: "Bilim", s: "Elektron alarak ya da vererek yüklü hale gelen atoma ne denir?", d: "İyon", y: ["İzotop", "Molekül"], a: "Elektron veren atom pozitif iyon (katyon), elektron alan atom negatif iyon (anyon) olur." },
  { id: "p12-063", k: "Bilim", s: "Çekirdeğinde bir proton ve bir nötron bulunan hidrojen izotopu hangisidir?", d: "Döteryum", y: ["Trityum", "Protiyum"], a: "Protiyumda nötron yoktur, döteryumda bir, trityumda iki nötron vardır." },
  { id: "p12-064", k: "Bilim", s: "Karbon-14 izotopu en çok hangi amaçla kullanılır?", d: "Yaş tayini", y: ["Yakıt üretimi", "Su arıtma"], a: "Karbon-14 yaklaşık 5.700 yıllık yarılanma ömrüyle bozunur. Bu sayede organik kalıntıların yaşı hesaplanabilir." },
  { id: "p12-065", k: "Bilim", s: "Karbon-12 atomunun çekirdeğinde kaç nötron vardır?", d: "6", y: ["12", "8"], a: "Kütle numarası 12, proton sayısı 6'dır. Nötron sayısı 12 - 6 = 6 olur." },
  { id: "p12-066", k: "Bilim", s: "Soy gazları kimyasal olarak kararlı kılan özellik nedir?", d: "Dış kabuklarının dolu olması", y: ["Çok ağır olmaları", "Metal olmaları"], a: "Soy gazların en dış elektron kabuğu doludur. Elektron alıp vermeye ihtiyaç duymadıkları için kararlıdırlar." },
  { id: "p12-067", k: "Bilim", s: "Tabelalarda kırmızı-turuncu ışık veren ünlü gaz hangisidir?", d: "Neon", y: ["Argon", "Ksenon"], a: "Neon tüpünden elektrik geçince kırmızı-turuncu parlar. Başka renkler için genellikle başka gazlar kullanılır." },
  { id: "p12-068", k: "Bilim", s: "Uçan balonlarda kullanılan, havadan hafif ve yanmayan gaz hangisidir?", d: "Helyum", y: ["Hidrojen", "Azot"], a: "Hidrojen de havadan hafiftir ama kolayca yanar. Helyum ise yanmaz, bu yüzden daha güvenlidir." },
  { id: "p12-069", k: "Bilim", s: "IUPAC'ın standart periyodik tablosunda kaç grup vardır?", d: "18", y: ["8", "16"], a: "Modern tabloda 1'den 18'e kadar numaralanan 18 grup bulunur. Eski sistemde 8 ana grup kullanılırdı." },
  { id: "p12-070", k: "Bilim", s: "Sodyum suyla tepkimeye girince hangi gaz açığa çıkar?", d: "Hidrojen", y: ["Oksijen", "Klor"], a: "Sodyum suyla sodyum hidroksit ve hidrojen gazı oluşturur. Tepkime çok hızlı ve ısı açığa çıkaran türdendir." },
  { id: "p12-071", k: "Bilim", s: "Bilgisayar çiplerinin temel malzemesi olan yarı metal hangisidir?", d: "Silisyum", y: ["Bakır", "Kükürt"], a: "Silisyum bir yarı iletkendir. Elektronik çiplerin büyük çoğunluğu saf silisyumdan yapılır." },
  { id: "p12-073", k: "Bilim", s: "Metaller arasında erime noktası en yüksek olan hangisidir?", d: "Tungsten", y: ["Demir", "Titanyum"], a: "Tungsten yaklaşık 3.400 °C'de erir. Bu yüzden eski ampullerin flamanlarında kullanılırdı." },
  { id: "p12-074", k: "Bilim", s: "Mıknatısın güçlü biçimde çektiği yaygın metal hangisidir?", d: "Demir", y: ["Bakır", "Alüminyum"], a: "Demir, nikel ve kobalt ferromanyetiktir. Bakır ve alüminyum mıknatısa yapışmaz." },
  { id: "p12-075", k: "Bilim", s: "Kemiklerde ve dişlerde en bol bulunan mineral element hangisidir?", d: "Kalsiyum", y: ["Sodyum", "Demir"], a: "Kemik ve dişlerin sertliği büyük ölçüde kalsiyum fosfat minerallerinden gelir." },
  { id: "p12-076", k: "Bilim", s: "Kandaki hemoglobinde bulunan ve oksijen bağlayan metal hangisidir?", d: "Demir", y: ["Bakır", "Çinko"], a: "Hemoglobindeki demir atomları oksijene bağlanır. Demir eksikliği bu yüzden kansızlığa yol açabilir." },
  { id: "p12-078", k: "Bilim", s: "Yapay yollarla üretilen ilk element hangisidir?", d: "Teknesyum", y: ["Plütonyum", "Neptünyum"], a: "Teknesyum 1937'de yapay olarak elde edildi. Adı Yunanca \"yapay\" anlamındaki \"technetos\"tan gelir." },
  { id: "p12-079", k: "Bilim", s: "Marie ve Pierre Curie'nin 1898'de keşfettiği iki element hangisidir?", d: "Polonyum ve radyum", y: ["Uranyum ve toryum", "Radon ve helyum"], a: "Curie'ler uranyum cevherinde bu iki radyoaktif elementi buldu. Marie Curie iki farklı bilim dalında Nobel kazandı." },
  { id: "p12-080", k: "Bilim", s: "Oda sıcaklığında katı olan ve ısıtılınca mor buhar veren halojen hangisidir?", d: "İyot", y: ["Flor", "Klor"], a: "İyot koyu gri-mor kristallerdir. Isıtılınca doğrudan mor renkli buhara dönüşür (süblimleşir)." },
  { id: "p12-081", k: "Bilim", s: "Sarımsı yeşil renkli, zehirli ve keskin kokulu gaz hangisidir?", d: "Klor", y: ["Azot", "Argon"], a: "Klor gazının adı Yunanca \"açık yeşil\" anlamına gelen \"chloros\"tan gelir." },
  { id: "p12-082", k: "Bilim", s: "Lantanitler ve aktinitler periyodik tabloda genellikle nerede gösterilir?", d: "Altta ayrı iki sırada", y: ["En sağ sütunda", "En üst satırda"], a: "Tablo çok genişlemesin diye bu iki seri ana tablonun altında ayrı satırlar halinde gösterilir." },
  { id: "p12-083", k: "Bilim", s: "Atom numarası 20 olan element hangisidir?", d: "Kalsiyum", y: ["Potasyum", "Magnezyum"], a: "Kalsiyumun 20 protonu vardır. Potasyum 19, magnezyum 12 atom numaralıdır." },
  { id: "p12-084", k: "Bilim", s: "Atom numarası 29 olan element hangisidir?", d: "Bakır", y: ["Çinko", "Nikel"], a: "Bakır 29, çinko 30, nikel 28 atom numaralıdır. Üçü de periyodik tabloda yan yanadır." },
  { id: "p12-085", k: "Bilim", s: "Atom numarası 13 olan element hangisidir?", d: "Alüminyum", y: ["Silisyum", "Magnezyum"], a: "Alüminyumun 13 protonu vardır. Silisyum 14, magnezyum 12 atom numaralıdır." },
  { id: "p12-086", k: "Bilim", s: "Atom numarası 16 olan element hangisidir?", d: "Kükürt", y: ["Fosfor", "Klor"], a: "Kükürdün 16 protonu vardır. Fosfor 15, klor 17 atom numaralıdır." },
  { id: "p12-087", k: "Bilim", s: "Topraktan sızıp evlerin bodrumunda birikebilen radyoaktif soy gaz hangisidir?", d: "Radon", y: ["Argon", "Kripton"], a: "Radon, topraktaki uranyumun bozunmasıyla oluşur. Kapalı alanlarda birikmesi sağlık açısından risklidir." },
  { id: "p12-088", k: "Bilim", s: "Karbon atomunun dış kabuğunda kaç elektron vardır?", d: "4", y: ["2", "6"], a: "Karbonun 4 değerlik elektronu vardır. Bu sayede dört bağ yapabilir ve sayısız bileşik oluşturur." },
  { id: "p12-089", k: "Bilim", s: "Periyodik tablonun 3-12. gruplarındaki elementlere ne denir?", d: "Geçiş metalleri", y: ["Alkali metaller", "Soy gazlar"], a: "Demir, bakır, altın ve gümüş gibi pek çok tanıdık metal geçiş metallerindendir." },
  { id: "p12-090", k: "Bilim", s: "\"Modern kimyanın babası\" olarak anılan Fransız bilim insanı kimdir?", d: "Antoine Lavoisier", y: ["Louis Pasteur", "Blaise Pascal"], a: "Lavoisier kütlenin korunumu ilkesini ortaya koydu ve oksijenin yanmadaki rolünü açıkladı." },
  { id: "p12-091", k: "Bilim", s: "1800'lerin başında modern atom kuramını ortaya atan İngiliz bilim insanı kimdir?", d: "John Dalton", y: ["Ernest Rutherford", "Michael Faraday"], a: "Dalton, her elementin kendine özgü atomlardan oluştuğunu ve atomların belirli oranlarda birleştiğini öne sürdü." },
  { id: "p12-095", k: "Bilim", s: "Nikelin kimyasal sembolü nedir?", d: "Ni", y: ["Nk", "N"], a: "Nikelin sembolü Ni'dir. Tek başına N ise azotun sembolüdür." },
  { id: "p12-096", k: "Bilim", s: "Titanyumun kimyasal sembolü nedir?", d: "Ti", y: ["T", "Tn"], a: "Titanyumun sembolü Ti'dir. Hafif ve dayanıklı olduğu için uçak parçalarında ve protezlerde kullanılır." },
  { id: "p12-097", k: "Bilim", s: "Argonun atom numarası kaçtır?", d: "18", y: ["20", "10"], a: "Argonun 18 protonu vardır ve 3. periyodun soy gazıdır." },
  { id: "p12-098", k: "Bilim", s: "Bir elementin kütle numarası neyin toplamıdır?", d: "Proton ve nötron sayısı", y: ["Proton ve elektron sayısı", "Yalnız nötron sayısı"], a: "Kütle numarası çekirdekteki proton ve nötronların toplamıdır. Elektronların kütlesi çok küçük olduğu için sayılmaz." },
  { id: "p12-099", k: "Bilim", s: "Periyodik tabloda metaller genel olarak hangi tarafta yer alır?", d: "Sol ve orta kısımda", y: ["Sağ üst köşede", "Yalnız en alt satırda"], a: "Metaller tablonun büyük bölümünü kaplar. Ametaller ağırlıklı olarak sağ üstte toplanır." },
  { id: "p12-100", k: "Bilim", s: "Elementlerin çoğu oda sıcaklığında hangi haldedir?", d: "Katı", y: ["Gaz", "Sıvı"], a: "Elementlerin büyük çoğunluğu katıdır. Oda sıcaklığında yalnızca iki element (cıva ve brom) sıvıdır, gazlar ise bir avuçtur." },
  { id: "p12-101", k: "Bilim", s: "Suyun kimyasal formülü nedir?", d: "H2O", y: ["H2O2", "HO2"], a: "Bir su molekülünde iki hidrojen ve bir oksijen atomu bulunur. H2O2 ise hidrojen peroksittir." },
  { id: "p12-102", k: "Bilim", s: "Sofra tuzunun kimyasal adı nedir?", d: "Sodyum klorür", y: ["Sodyum bikarbonat", "Kalsiyum karbonat"], a: "Sofra tuzu sodyum klorürdür, formülü NaCl'dir." },
  { id: "p12-103", k: "Bilim", s: "Karbondioksitin kimyasal formülü nedir?", d: "CO2", y: ["CO", "C2O"], a: "Karbondioksitte bir karbon ve iki oksijen atomu vardır. CO ise karbonmonoksittir." },
  { id: "p12-104", k: "Bilim", s: "Karbonmonoksit gazı vücutta neden tehlikelidir?", d: "Kanın oksijen taşımasını engeller", y: ["Kemikleri eritir", "Mideyi tahriş eder"], a: "Karbonmonoksit hemoglobine oksijenden çok daha sıkı bağlanır. Renksiz ve kokusuz olduğu için fark edilmesi zordur." },
  { id: "p12-105", k: "Bilim", s: "Mutfakta \"karbonat\" denen yemek sodasının kimyasal adı nedir?", d: "Sodyum bikarbonat", y: ["Sodyum klorür", "Kalsiyum oksit"], a: "Yemek sodası sodyum bikarbonattır (NaHCO3). Asitle karşılaşınca karbondioksit açığa çıkarır." },
  { id: "p12-106", k: "Bilim", s: "Kireç taşı ve mermerin ana bileşeni hangisidir?", d: "Kalsiyum karbonat", y: ["Sodyum klorür", "Silisyum dioksit"], a: "Kireç taşı ve mermer büyük ölçüde kalsiyum karbonattan (CaCO3) oluşur." },
  { id: "p12-107", k: "Bilim", s: "Kuvars kumunun ana bileşeni hangisidir?", d: "Silisyum dioksit", y: ["Kalsiyum karbonat", "Alüminyum oksit"], a: "Kuvars, silisyum dioksittir (SiO2). Cam yapımında ana hammadde olarak kullanılır." },
  { id: "p12-108", k: "Bilim", s: "Amonyağın kimyasal formülü nedir?", d: "NH3", y: ["NH4", "N2H"], a: "Amonyak bir azot ve üç hidrojen atomundan oluşur. NH4+ ise amonyum iyonudur." },
  { id: "p12-109", k: "Bilim", s: "Metan gazının kimyasal formülü nedir?", d: "CH4", y: ["C2H6", "CH3"], a: "Metan, bir karbon ve dört hidrojen atomundan oluşan en basit hidrokarbondur. C2H6 etandır." },
  { id: "p12-110", k: "Bilim", s: "Doğal gazın büyük bölümünü hangi gaz oluşturur?", d: "Metan", y: ["Propan", "Bütan"], a: "Doğal gaz çoğunlukla metandır. Propan ve bütan ise tüp gazın (LPG) ana bileşenleridir." },
  { id: "p12-111", k: "Bilim", s: "Ozon molekülünün formülü nedir?", d: "O3", y: ["O2", "O4"], a: "Ozon üç oksijen atomundan oluşur. Soluduğumuz oksijen gazı ise O2'dir." },
  { id: "p12-112", k: "Bilim", s: "Sülfürik asidin kimyasal formülü nedir?", d: "H2SO4", y: ["HNO3", "H2CO3"], a: "Sülfürik asit sanayide en çok üretilen kimyasallardan biridir. HNO3 nitrik asit, H2CO3 karbonik asittir." },
  { id: "p12-113", k: "Bilim", s: "Midede sindirime yardım eden asit hangisidir?", d: "Hidroklorik asit", y: ["Sülfürik asit", "Asetik asit"], a: "Mide özsuyu hidroklorik asit (HCl) içerir. Bu asit besinleri parçalamaya ve mikropları öldürmeye yardım eder." },
  { id: "p12-114", k: "Bilim", s: "Sirkeye ekşi tadını veren asit hangisidir?", d: "Asetik asit", y: ["Sitrik asit", "Laktik asit"], a: "Sirke, yaklaşık %4-8 oranında asetik asit içeren sulu bir çözeltidir." },
  { id: "p12-115", k: "Bilim", s: "Limon ve portakalda bol bulunan asit hangisidir?", d: "Sitrik asit", y: ["Asetik asit", "Formik asit"], a: "Turunçgillerin ekşiliği büyük ölçüde sitrik asitten gelir. Adı Latince \"citrus\"tan türemiştir." },
  { id: "p12-116", k: "Bilim", s: "Adını karıncadan alan ve karınca salgısında bulunan asit hangisidir?", d: "Formik asit", y: ["Laktik asit", "Oksalik asit"], a: "Latincede karınca \"formica\" demektir. Formik asit ilk kez karıncalardan elde edilmiştir." },
  { id: "p12-117", k: "Bilim", s: "Sütün yoğurda dönüşürken ekşimesine yol açan asit hangisidir?", d: "Laktik asit", y: ["Sitrik asit", "Nitrik asit"], a: "Bakteriler sütteki laktozu laktik aside dönüştürür. Süt asitleşince proteinler pıhtılaşır ve yoğurt kıvamı oluşur." },
  { id: "p12-118", k: "Bilim", s: "25 °C'deki saf suyun pH değeri kaçtır?", d: "7", y: ["0", "14"], a: "Saf su nötrdür ve pH değeri 7'dir. 7'nin altı asidik, üstü bazik kabul edilir." },
  { id: "p12-119", k: "Bilim", s: "pH değeri 7'den küçük olan çözeltilere ne denir?", d: "Asidik", y: ["Bazik", "Nötr"], a: "pH düştükçe asitlik artar. Örneğin limon suyunun pH'ı 2 civarındadır." },
  { id: "p12-120", k: "Bilim", s: "Mavi turnusol kâğıdı asidik bir çözeltiye batırılınca hangi renge döner?", d: "Kırmızı", y: ["Yeşil", "Mor"], a: "Asitler mavi turnusolü kırmızıya, bazlar kırmızı turnusolü maviye çevirir." },
  { id: "p12-121", k: "Bilim", s: "Asit ile bazın tepkimeye girip tuz ve su oluşturmasına ne denir?", d: "Nötrleşme", y: ["Yanma", "Paslanma"], a: "Nötrleşmede asidin H+ iyonları ile bazın OH- iyonları birleşip su oluşturur." },
  { id: "p12-122", k: "Bilim", s: "Sodyum hidroksitin halk arasındaki yaygın adı nedir?", d: "Sud kostik", y: ["Kezzap", "Tuz ruhu"], a: "Sud kostik (NaOH) güçlü bir bazdır. Kezzap nitrik asidin, tuz ruhu hidroklorik asidin yaygın adıdır." },
  { id: "p12-123", k: "Bilim", s: "Çamaşır suyunun etken maddesi hangisidir?", d: "Sodyum hipoklorit", y: ["Sodyum klorür", "Sodyum bikarbonat"], a: "Çamaşır suyu, sodyum hipokloritin sulu çözeltisidir. Ağartıcı ve mikrop öldürücü etkisi buradan gelir." },
  { id: "p12-124", k: "Bilim", s: "Çamaşır suyu tuz ruhuyla karıştırılırsa hangi zehirli gaz açığa çıkar?", d: "Klor", y: ["Helyum", "Azot"], a: "Bu karışım klor gazı çıkarır ve solunduğunda ciddi zarar verir. Temizlik ürünleri asla karıştırılmamalıdır." },
  { id: "p12-125", k: "Bilim", s: "Tuz ruhu hangi asidin sulu çözeltisidir?", d: "Hidroklorik asit", y: ["Sülfürik asit", "Nitrik asit"], a: "Tuz ruhu, hidrojen klorür gazının suda çözünmesiyle elde edilen hidroklorik asittir." },
  { id: "p12-126", k: "Bilim", s: "Yağların bazla tepkimeye girip sabun oluşturmasına ne denir?", d: "Sabunlaşma", y: ["Damıtma", "Mayalanma"], a: "Sabunlaşmada yağlar sud kostik gibi güçlü bir bazla tepkimeye girer ve sabun ile gliserin oluşur." },
  { id: "p12-127", k: "Bilim", s: "Demirin paslanması için hangi iki madde gerekir?", d: "Oksijen ve su", y: ["Azot ve tuz", "Helyum ve su"], a: "Demir, nem ve oksijenin birlikte bulunduğu ortamda paslanır. Tuz bu süreci hızlandırır." },
  { id: "p12-128", k: "Bilim", s: "Demir pası kimyasal olarak nedir?", d: "Demir oksit", y: ["Demir sülfat", "Demir karbür"], a: "Pas, su içeren demir(III) oksittir. Demirin oksijen ve nemle tepkimesinden oluşur." },
  { id: "p12-129", k: "Bilim", s: "Isı alarak gerçekleşen kimyasal tepkimelere ne ad verilir?", d: "Endotermik", y: ["Ekzotermik", "Katalitik"], a: "Endotermik tepkimeler çevreden ısı alır. Isı veren tepkimelere ise ekzotermik denir." },
  { id: "p12-130", k: "Bilim", s: "Tepkimeyi hızlandırıp kendisi tükenmeyen maddeye ne denir?", d: "Katalizör", y: ["İnhibitör", "Çözücü"], a: "Katalizör tepkimenin daha düşük enerjiyle gerçekleşmesini sağlar. Arabalardaki katalitik konvertör buna örnektir." },
  { id: "p12-131", k: "Bilim", s: "Canlılarda tepkimeleri hızlandıran protein yapılı moleküllere ne denir?", d: "Enzim", y: ["Hormon", "Vitamin"], a: "Enzimler biyolojik katalizörlerdir. Örneğin tükürükteki amilaz nişastayı parçalar." },
  { id: "p12-133", k: "Bilim", s: "Bir maddenin gaz halden sıvı hale geçmesine ne denir?", d: "Yoğuşma", y: ["Donma", "Süblimleşme"], a: "Soğuk bir bardağın dışında oluşan su damlaları, havadaki su buharının yoğuşmasıdır." },
  { id: "p12-134", k: "Bilim", s: "\"Kuru buz\" aslında nedir?", d: "Katı karbondioksit", y: ["Katı azot", "Katı oksijen"], a: "Kuru buz -78 °C civarında süblimleşir. Erimeden doğrudan gaza dönüştüğü için ıslaklık bırakmaz." },
  { id: "p12-135", k: "Bilim", s: "Deniz seviyesinde saf su kaç °C'de kaynar?", d: "100 °C", y: ["90 °C", "120 °C"], a: "Deniz seviyesindeki normal basınçta saf su 100 °C'de kaynar. Basınç düşünce kaynama sıcaklığı da düşer." },
  { id: "p12-136", k: "Bilim", s: "Su en yüksek yoğunluğa yaklaşık kaç °C'de ulaşır?", d: "4 °C", y: ["0 °C", "100 °C"], a: "Su yaklaşık 4 °C'de en yoğundur. Bu yüzden göllerin dibi kışın bile çoğunlukla donmaz." },
  { id: "p12-137", k: "Bilim", s: "Buz suyun üzerinde neden yüzer?", d: "Yoğunluğu sudan düşük", y: ["İçi havayla dolu", "Su molekülleri iter"], a: "Su donarken molekülleri daha geniş bir düzenle dizilir. Bu yüzden buz, sıvı sudan yaklaşık %9 daha az yoğundur." },
  { id: "p12-138", k: "Bilim", s: "Yıldızlarda bulunan, maddenin iyonlaşmış gaz haline ne denir?", d: "Plazma", y: ["Jel", "Kristal"], a: "Plazma, elektronları atomlarından ayrılmış sıcak bir gazdır. Güneş ve şimşek plazma örnekleridir." },
  { id: "p12-139", k: "Bilim", s: "Suya tuz eklemek suyun donma noktasını nasıl etkiler?", d: "Düşürür", y: ["Yükseltir", "Değiştirmez"], a: "Tuzlu su 0 °C'nin altında donar. Kışın yollara tuz serpilmesinin nedeni budur." },
  { id: "p12-140", k: "Bilim", s: "Yüksek bir dağın tepesinde su hangi sıcaklıkta kaynar?", d: "100 °C'nin altında", y: ["100 °C'nin üstünde", "Tam 100 °C'de"], a: "Yükseklerde hava basıncı düşüktür, bu yüzden su daha düşük sıcaklıkta kaynar ve yemekler geç pişer." },
  { id: "p12-141", k: "Bilim", s: "Düdüklü tencere yemeği neden daha hızlı pişirir?", d: "Suyun kaynama noktası yükselir", y: ["Su daha az buharlaşır", "Tencere ısıyı yansıtır"], a: "Kapalı tencerede basınç artar ve su 100 °C'nin üstünde kaynar. Daha sıcak su yemeği daha çabuk pişirir." },
  { id: "p12-142", k: "Bilim", s: "Tunç (bronz) alaşımı temel olarak hangi metallerden oluşur?", d: "Bakır ve kalay", y: ["Bakır ve çinko", "Demir ve karbon"], a: "Tunç, bakır ve kalay alaşımıdır. Tunç Çağı adını bu dayanıklı alaşımdan alır." },
  { id: "p12-143", k: "Bilim", s: "Pirinç alaşımı hangi metallerden oluşur?", d: "Bakır ve çinko", y: ["Bakır ve kalay", "Demir ve krom"], a: "Pirinç sarı renkli bir bakır-çinko alaşımıdır. Musluk ve kapı kollarında yaygın olarak kullanılır." },
  { id: "p12-144", k: "Bilim", s: "Çelik temel olarak hangi iki elementten oluşur?", d: "Demir ve karbon", y: ["Bakır ve kalay", "Alüminyum ve çinko"], a: "Çelik, az miktarda karbon içeren demirdir. Karbon demiri daha sert ve dayanıklı yapar." },
  { id: "p12-145", k: "Bilim", s: "Paslanmaz çeliğe paslanmama özelliği kazandıran element hangisidir?", d: "Krom", y: ["Kurşun", "Bakır"], a: "Paslanmaz çelik en az yaklaşık %10,5 krom içerir. Krom yüzeyde korozyonu önleyen ince bir oksit tabakası oluşturur." },
  { id: "p12-146", k: "Bilim", s: "24 ayar altın ne anlama gelir?", d: "Saf altın", y: ["Yarı yarıya altın", "Dörtte üçü altın"], a: "Ayar sistemi 24 parça üzerinden hesaplanır. 24 ayar, karışım içermeyen (pratikte %99,9) altındır." },
  { id: "p12-147", k: "Bilim", s: "18 ayar altında kütlece ne kadar altın bulunur?", d: "%75", y: ["%50", "%90"], a: "18/24 = 0,75'tir. Yani 18 ayar bir takının dörtte üçü altın, kalanı başka metallerdir." },
  { id: "p12-148", k: "Bilim", s: "14 ayar altında kütlece yaklaşık ne kadar altın bulunur?", d: "%58,5", y: ["%40", "%70"], a: "14/24 yaklaşık 0,583 eder. Kuyumcularda bu ayar \"585\" damgasıyla gösterilir." },
  { id: "p12-149", k: "Bilim", s: "Cıvanın başka bir metalle oluşturduğu alaşıma ne denir?", d: "Amalgam", y: ["Bronz", "Pirinç"], a: "Amalgam, cıva içeren alaşımdır. Eski diş dolgularında gümüş-cıva amalgamı kullanılırdı." },
  { id: "p12-150", k: "Bilim", s: "Alüminyumun elde edildiği başlıca cevher hangisidir?", d: "Boksit", y: ["Hematit", "Galen"], a: "Alüminyum boksitten elde edilir. Hematit demirin, galen kurşunun cevheridir." },
  { id: "p12-151", k: "Bilim", s: "Güvenli kibrit kutusunun sürtme yüzeyinde hangi element bulunur?", d: "Fosfor", y: ["Sodyum", "Kalsiyum"], a: "Sürtme yüzeyindeki kırmızı fosfor, kibrit başıyla sürtününce tutuşmayı başlatır." },
  { id: "p12-152", k: "Bilim", s: "Kabartma tozu hamuru hangi gazı açığa çıkararak kabartır?", d: "Karbondioksit", y: ["Oksijen", "Azot"], a: "Kabartma tozu ısı ve nemle karbondioksit gazı çıkarır. Bu kabarcıklar hamuru kabartır." },
  { id: "p12-153", k: "Bilim", s: "Maya, şekeri fermente ettiğinde hangi iki ürünü oluşturur?", d: "Alkol ve karbondioksit", y: ["Su ve oksijen", "Tuz ve su"], a: "Maya mantarları şekeri etil alkole ve karbondioksite dönüştürür. Ekmekte gaz hamuru kabartır, alkol fırında uçar." },
  { id: "p12-154", k: "Bilim", s: "Kesilen elmanın kısa sürede kararmasına yol açan olay hangisidir?", d: "Oksitlenme", y: ["Buharlaşma", "Süblimleşme"], a: "Elmadaki enzimler havadaki oksijenle tepkimeye girerek kahverengi maddeler oluşturur. Limon suyu bu süreci yavaşlatır." },
  { id: "p12-155", k: "Bilim", s: "Glikozun kimyasal formülü nedir?", d: "C6H12O6", y: ["C12H22O11", "C2H5OH"], a: "Glikoz altı karbonlu basit bir şekerdir. C12H22O11 sofra şekeri (sakaroz), C2H5OH ise etil alkoldür." },
  { id: "p12-156", k: "Bilim", s: "Sahte içkilerde bulunabilen ve körlüğe yol açabilen alkol hangisidir?", d: "Metanol", y: ["Etanol", "Gliserin"], a: "Metanol vücutta zehirli formik aside dönüşür. Az miktarı bile görme sinirine kalıcı zarar verebilir." },
  { id: "p12-157", k: "Bilim", s: "Çürük yumurta kokusuyla bilinen gaz hangisidir?", d: "Hidrojen sülfür", y: ["Amonyak", "Metan"], a: "Hidrojen sülfür (H2S) çürük yumurta kokar. Yüksek derişimde zehirlidir." },
  { id: "p12-158", k: "Bilim", s: "\"Gülme gazı\" olarak bilinen gaz hangisidir?", d: "Diazot monoksit", y: ["Azot dioksit", "Amonyak"], a: "Diazot monoksit (N2O) diş hekimliğinde ve ameliyatlarda hafif uyuşturucu olarak kullanılır." },
  { id: "p12-159", k: "Bilim", s: "Ozon tabakasının incelmesine yol açan başlıca kimyasallar hangileridir?", d: "Kloroflorokarbonlar (CFC)", y: ["Soy gazlar", "Silikatlar"], a: "Eski spreylerde ve buzdolaplarında kullanılan CFC'ler 1987 Montreal Protokolü ile aşamalı olarak yasaklandı." },
  { id: "p12-160", k: "Bilim", s: "Asit yağmurlarına yol açan başlıca gazlar hangileridir?", d: "Kükürt ve azot oksitleri", y: ["Helyum ve neon", "Oksijen ve argon"], a: "Kükürt dioksit ve azot oksitleri havadaki suyla birleşerek asit oluşturur. Kaynakları çoğunlukla fosil yakıtlardır." },
  { id: "p12-161", k: "Bilim", s: "Kokusuz doğal gaza neden özel bir koku eklenir?", d: "Sızıntı fark edilsin diye", y: ["Daha iyi yansın diye", "Rengi değişsin diye"], a: "Metan kokusuzdur. Eklenen kükürtlü koku maddeleri sayesinde gaz kaçağı burnumuzla fark edilebilir." },
  { id: "p12-162", k: "Bilim", s: "Mutfak tüplerindeki LPG başlıca hangi gazlardan oluşur?", d: "Propan ve bütan", y: ["Metan ve etan", "Hidrojen ve helyum"], a: "LPG, sıvılaştırılmış petrol gazıdır. Basınç altında sıvı tutulan propan ve bütan karışımıdır." },
  { id: "p12-163", k: "Bilim", s: "Etin pişerken kızarıp lezzetlenmesini sağlayan tepkimeye ne denir?", d: "Maillard tepkimesi", y: ["Sabunlaşma", "Elektroliz"], a: "Maillard tepkimesi şekerler ve amino asitler arasında yüksek ısıda gerçekleşir. Ekmek kabuğunun rengi de buradan gelir." },
  { id: "p12-164", k: "Bilim", s: "Suyu elektrik akımıyla hidrojen ve oksijene ayırma işlemine ne denir?", d: "Elektroliz", y: ["Damıtma", "Süzme"], a: "Elektrolizde elektrik enerjisi kimyasal bağları koparır. Bu yöntem hidrojen üretiminde de kullanılır." },
  { id: "p12-165", k: "Bilim", s: "Suyun elektrolizinde oluşan hidrojen ve oksijen gazlarının hacim oranı nedir?", d: "2'ye 1", y: ["1'e 1", "1'e 2"], a: "Su molekülünde iki hidrojene bir oksijen düşer. Bu yüzden hidrojen gazı oksijenin iki katı hacimde toplanır." },
  { id: "p12-166", k: "Bilim", s: "Damıtma yöntemi sıvıları hangi farka göre ayırır?", d: "Kaynama noktası", y: ["Renk", "Manyetik özellik"], a: "Karışım ısıtılınca kaynama noktası düşük olan bileşen önce buharlaşır, sonra soğutularak ayrı toplanır." },
  { id: "p12-167", k: "Bilim", s: "Ham petrolü benzin, mazot gibi bileşenlerine ayırmak için hangi yöntem kullanılır?", d: "Ayrımsal damıtma", y: ["Süzme", "Mıknatısla ayırma"], a: "Rafinerilerde ham petrol ısıtılır ve farklı kaynama noktalarına sahip bileşenler kulenin farklı katlarında toplanır." },
  { id: "p12-168", k: "Bilim", s: "Avogadro sayısının yaklaşık değeri nedir?", d: "6,02 × 10²³", y: ["9,81 × 10²³", "3,14 × 10²³"], a: "Bir mol maddede yaklaşık 6,02 × 10²³ tanecik bulunur. Bu sayıya Avogadro sayısı denir." },
  { id: "p12-169", k: "Bilim", s: "Suyun mol kütlesi yaklaşık kaç gramdır?", d: "18 g", y: ["16 g", "20 g"], a: "Hidrojen yaklaşık 1, oksijen 16 kütle birimidir. 2 × 1 + 16 = 18 g/mol eder." },
  { id: "p12-170", k: "Bilim", s: "Kovalent bağ nasıl oluşur?", d: "Elektronların ortaklaşa kullanılmasıyla", y: ["Elektron aktarımıyla", "Proton paylaşımıyla"], a: "Kovalent bağda atomlar elektron çiftlerini paylaşır. Su ve metan moleküllerindeki bağlar kovalenttir." },
  { id: "p12-171", k: "Bilim", s: "Sofra tuzunda (NaCl) sodyum ile klor arasındaki bağ türü nedir?", d: "İyonik bağ", y: ["Kovalent bağ", "Metalik bağ"], a: "Sodyum bir elektronunu klora verir. Oluşan zıt yüklü iyonlar birbirini çekerek iyonik bağ kurar." },
  { id: "p12-172", k: "Bilim", s: "Bir su molekülünde toplam kaç atom vardır?", d: "3", y: ["2", "4"], a: "Bir su molekülünde iki hidrojen ve bir oksijen olmak üzere üç atom bulunur." },
  { id: "p12-173", k: "Bilim", s: "Kapalı bir kapta gerçekleşen kimyasal tepkimede toplam kütleye ne olur?", d: "Değişmez", y: ["Artar", "Azalır"], a: "Kütlenin korunumu ilkesine göre tepkimede atomlar yok olmaz ya da yoktan var olmaz, yalnızca yeniden düzenlenir." },
  { id: "p12-174", k: "Bilim", s: "Hangisi bazik bir maddedir?", d: "Sabunlu su", y: ["Limon suyu", "Sirke"], a: "Sabunlu su baziktir, kaygan bir his verir. Limon suyu ve sirke ise asidiktir." },
  { id: "p12-175", k: "Bilim", s: "Mide ekşimesinde kullanılan antiasit ilaçlar nasıl etki eder?", d: "Mide asidini nötrleştirir", y: ["Mide asidini artırır", "Mideyi soğutur"], a: "Antiasitler genellikle magnezyum hidroksit, kalsiyum karbonat gibi bazlar içerir ve fazla asidi nötrleştirir." },
  { id: "p12-176", k: "Bilim", s: "Sönmemiş kirecin kimyasal adı nedir?", d: "Kalsiyum oksit", y: ["Kalsiyum karbonat", "Kalsiyum klorür"], a: "Sönmemiş kireç (CaO), kireç taşının ısıtılmasıyla elde edilir. Suyla tepkimeye girince sönmüş kirece dönüşür." },
  { id: "p12-177", k: "Bilim", s: "Suyun sert olmasına başlıca hangi iyonlar yol açar?", d: "Kalsiyum ve magnezyum", y: ["Sodyum ve potasyum", "Demir ve bakır"], a: "Sert suda çözünmüş kalsiyum ve magnezyum iyonları boldur. Isıtılınca çaydanlıkta kireç bırakır." },
  { id: "p12-178", k: "Bilim", s: "Alçı taşının kimyasal adı nedir?", d: "Kalsiyum sülfat", y: ["Kalsiyum karbonat", "Sodyum sülfat"], a: "Alçı taşı (jips), su içeren kalsiyum sülfattır. Isıtılınca inşaatta kullanılan alçı elde edilir." },
  { id: "p12-179", k: "Bilim", s: "Hidrojen gazı oksijenle yandığında ne oluşur?", d: "Su", y: ["Karbondioksit", "Amonyak"], a: "Hidrojen yanınca yalnız su buharı oluşur. Bu yüzden hidrojen temiz bir yakıt olarak görülür." },
  { id: "p12-180", k: "Bilim", s: "Eski fotoğraf filmlerindeki ışığa duyarlı bileşikler hangi metali içerir?", d: "Gümüş", y: ["Altın", "Kurşun"], a: "Fotoğraf filmlerinde gümüş halojenür kristalleri kullanılır. Işık bu kristallerde görüntü izini oluşturur." },
  { id: "p12-181", k: "Bilim", s: "Ray kaynağında kullanılan termit karışımında demir oksitle tepkimeye giren metal hangisidir?", d: "Alüminyum", y: ["Bakır", "Çinko"], a: "Termit tepkimesinde alüminyum, demir oksitten oksijeni alır. Açığa çıkan büyük ısı erimiş demir oluşturur." },
  { id: "p12-182", k: "Bilim", s: "Havai fişeklerde parlak kırmızı rengi veren element hangisidir?", d: "Stronsiyum", y: ["Sodyum", "Bakır"], a: "Stronsiyum tuzları kırmızı renk verir. Sodyum sarı, bakır ise mavi-yeşil tonlar oluşturur." },
  { id: "p12-183", k: "Bilim", s: "Eski sokak lambalarının turuncu-sarı ışığı hangi elementin buharından gelir?", d: "Sodyum", y: ["Neon", "Cıva"], a: "Sodyum buharlı lambalar kendine özgü turuncu-sarı ışık yayar. Verimli oldukları için uzun süre sokaklarda kullanıldılar." },
  { id: "p12-184", k: "Bilim", s: "Fritz Haber hangi bileşiği havadaki azottan büyük ölçekte üretmenin yolunu buldu?", d: "Amonyak", y: ["Metan", "Ozon"], a: "Haber-Bosch yöntemiyle azot ve hidrojenden amonyak üretilir. Bu amonyak gübre yapımının temelidir." },
  { id: "p12-185", k: "Bilim", s: "Dinamiti icat eden ve adını taşıyan ödülleri vasiyet eden kimyager kimdir?", d: "Alfred Nobel", y: ["Fritz Haber", "Robert Boyle"], a: "İsveçli Alfred Nobel dinamiti 1867'de patentledi. Servetini Nobel ödüllerinin kurulması için bıraktı." },
  { id: "p12-186", k: "Bilim", s: "Kauçuğu dayanıklı hale getiren vulkanizasyonda hangi element kullanılır?", d: "Kükürt", y: ["Azot", "Klor"], a: "Kauçuk kükürtle ısıtılınca molekülleri arasında bağlar oluşur. Böylece daha sağlam ve esnek olur; araba lastikleri bu yöntemle üretilir." },
  { id: "p12-187", k: "Bilim", s: "Sabit sıcaklıkta bir gazın basıncı ile hacminin ters orantılı olduğunu söyleyen yasa hangisidir?", d: "Boyle yasası", y: ["Charles yasası", "Avogadro yasası"], a: "Robert Boyle bu ilişkiyi 1662'de yayımladı. Gaz sıkıştırılınca basıncı artar." },
  { id: "p12-188", k: "Bilim", s: "Kimya ve Barış dallarında tek başına iki Nobel kazanan bilim insanı kimdir?", d: "Linus Pauling", y: ["Marie Curie", "Alfred Nobel"], a: "Pauling 1954'te Kimya, 1962'de Barış ödülünü aldı. İki Nobel'i de paylaşmadan kazanan tek kişidir." },
  { id: "p12-189", k: "Bilim", s: "Diş macunlarına çürüğe karşı bileşik halinde eklenen element hangisidir?", d: "Flor", y: ["Klor", "Brom"], a: "Florür, diş minesini güçlendirir ve asitlere karşı daha dayanıklı hale getirir." },
  { id: "p12-190", k: "Bilim", s: "Guatra karşı sofra tuzuna eklenen element hangisidir?", d: "İyot", y: ["Flor", "Demir"], a: "Tiroit bezi hormon üretmek için iyota ihtiyaç duyar. İyot eksikliği guatra yol açabilir." },
  { id: "p12-191", k: "Bilim", s: "Hidrojen peroksitin kimyasal formülü nedir?", d: "H2O2", y: ["H2O", "HO3"], a: "Hidrojen peroksit, suya göre fazladan bir oksijen içerir. Seyreltik çözeltisi yara temizliğinde ve ağartmada kullanılır." },
  { id: "p12-192", k: "Bilim", s: "Bir maddenin sıvı halden katı hale geçmesine ne denir?", d: "Donma", y: ["Erime", "Yoğuşma"], a: "Donma, erimenin tersidir. Saf bir madde aynı sıcaklıkta erir ve donar." },
  { id: "p12-193", k: "Bilim", s: "Naftalinin dolapta zamanla küçülüp kaybolması hangi olaydır?", d: "Süblimleşme", y: ["Erime", "Yoğuşma"], a: "Naftalin oda sıcaklığında sıvılaşmadan yavaş yavaş gaz haline geçer." },
  { id: "p12-194", k: "Bilim", s: "Tuzlu sudan tuzu geri elde etmenin en basit yolu hangisidir?", d: "Suyu buharlaştırmak", y: ["Süzgeçten geçirmek", "Mıknatısla çekmek"], a: "Tuz suda çözündüğü için süzgeçte kalmaz. Su buharlaştırılınca tuz kristaller halinde geride kalır." },
  { id: "p12-195", k: "Bilim", s: "Kimyada \"Na\" sembolü hangi elemente aittir?", d: "Sodyum", y: ["Nikel", "Neon"], a: "Na sodyumun sembolüdür. Nikel Ni, neon ise Ne ile gösterilir." },
  { id: "p12-196", k: "Bilim", s: "Kimyada \"K\" sembolü hangi elemente aittir?", d: "Potasyum", y: ["Kalsiyum", "Kükürt"], a: "K, potasyumun sembolüdür. Kalsiyum Ca, kükürt S ile gösterilir." },
  { id: "p12-197", k: "Bilim", s: "Bakır yüzeylerde zamanla oluşan yeşil tabakaya ne denir?", d: "Bakır pası (patina)", y: ["Kireç", "İs"], a: "Bakır hava, nem ve karbondioksitle yeşil bir tabaka oluşturur. Özgürlük Heykeli'nin yeşil rengi bu yüzdendir." },
  { id: "p12-198", k: "Bilim", s: "Tencere ve uçak gövdelerinde kullanılan hafif, gümüş renkli metal hangisidir?", d: "Alüminyum", y: ["Kurşun", "Cıva"], a: "Alüminyum hafiftir ve yüzeyinde koruyucu bir oksit tabakası oluşur. Bu yüzden kolay kolay paslanmaz." },
  { id: "p12-199", k: "Bilim", s: "Saf altın neden takılarda diğer metallerle karıştırılır?", d: "Çok yumuşak olduğu için", y: ["Çok ağır olduğu için", "Çabuk paslandığı için"], a: "Saf altın kolayca çizilir ve şekil değiştirir. Bakır, gümüş gibi metallerle karıştırılınca sertleşir." },
  { id: "p12-200", k: "Bilim", s: "Kurşun kalemin içindeki gri madde nedir?", d: "Grafit", y: ["Kurşun", "Kömür tozu"], a: "Kurşun kalemlerde kurşun yoktur. İçi grafit ve kil karışımıdır." },
  { id: "p12-201", k: "Bilim", s: "Pi sayısının yaklaşık değeri nedir?", d: "3,14", y: ["2,72", "1,62"], a: "Pi yaklaşık 3,14159'dur. 2,72 e sayısının, 1,62 ise altın oranın yaklaşık değeridir." },
  { id: "p12-202", k: "Bilim", s: "Pi sayısı bir çemberde neyin neye oranıdır?", d: "Çevrenin çapa oranı", y: ["Alanın yarıçapa oranı", "Çapın yarıçapa oranı"], a: "Büyük ya da küçük, her çemberin çevresi çapının yaklaşık 3,14 katıdır." },
  { id: "p12-203", k: "Bilim", s: "Pi Günü her yıl hangi tarihte kutlanır?", d: "14 Mart", y: ["22 Mart", "1 Nisan"], a: "Amerikan tarih yazımında 14 Mart 3/14 diye yazılır ve pi'nin ilk basamaklarını andırır." },
  { id: "p12-204", k: "Bilim", s: "Pi için okullarda sık kullanılan kesirli yaklaşık değer hangisidir?", d: "22/7", y: ["7/22", "3/14"], a: "22/7 yaklaşık 3,1429 eder ve pi'ye oldukça yakındır. Ama pi'nin tam değeri değildir." },
  { id: "p12-205", k: "Bilim", s: "Pi sayısı hangi tür sayıdır?", d: "İrrasyonel sayı", y: ["Tam sayı", "Rasyonel sayı"], a: "Pi iki tam sayının oranı olarak yazılamaz. Ondalık basamakları tekrar etmeden sonsuza kadar sürer." },
  { id: "p12-206", k: "Bilim", s: "Pi'yi çemberin içine ve dışına çizdiği çokgenlerle hesaplayan antik bilgin kimdir?", d: "Arşimet", y: ["Pisagor", "Thales"], a: "Arşimet 96 kenarlı çokgenler kullanarak pi'nin 3 10/71 ile 3 1/7 arasında olduğunu gösterdi." },
  { id: "p12-207", k: "Bilim", s: "Yarıçapı r olan bir çemberin çevresi hangi formülle bulunur?", d: "2πr", y: ["πr²", "πr/2"], a: "Çevre = 2 × π × yarıçap. πr² ise dairenin alan formülüdür." },
  { id: "p12-208", k: "Bilim", s: "Yarıçapı r olan bir dairenin alanı hangi formülle bulunur?", d: "πr²", y: ["2πr", "4πr"], a: "Dairenin alanı pi ile yarıçapın karesinin çarpımıdır." },
  { id: "p12-209", k: "Bilim", s: "π = 3 alınırsa yarıçapı 10 cm olan dairenin alanı kaç cm² olur?", d: "300", y: ["60", "100"], a: "Alan = π × r² = 3 × 10 × 10 = 300 cm²." },
  { id: "p12-210", k: "Bilim", s: "En küçük asal sayı kaçtır?", d: "2", y: ["1", "3"], a: "2 aynı zamanda tek çift asal sayıdır. 1 ise tanım gereği asal sayılmaz." },
  { id: "p12-211", k: "Bilim", s: "1 ile 20 arasında kaç asal sayı vardır?", d: "8", y: ["7", "10"], a: "Bu asallar 2, 3, 5, 7, 11, 13, 17 ve 19'dur." },
  { id: "p12-212", k: "Bilim", s: "Hangisi bir asal sayıdır?", d: "97", y: ["91", "87"], a: "97 yalnızca 1'e ve kendisine bölünür. 91 = 7 × 13, 87 = 3 × 29 eder." },
  { id: "p12-213", k: "Bilim", s: "51, 53 ve 57 sayılarından hangisi asaldır?", d: "53", y: ["51", "57"], a: "51 = 3 × 17 ve 57 = 3 × 19'dur. 53 ise yalnız 1'e ve kendisine bölünür." },
  { id: "p12-214", k: "Bilim", s: "Asal sayıların sonsuz sayıda olduğunu ilk kanıtlayan matematikçi kimdir?", d: "Öklid", y: ["Pisagor", "Fermat"], a: "Öklid bu kanıtı MÖ 300 civarında yazdığı Elemanlar adlı eserinde verdi." },
  { id: "p12-215", k: "Bilim", s: "Asal sayıları bulmak için katları eleyen ünlü yöntemin adı nedir?", d: "Eratosthenes kalburu", y: ["Pascal üçgeni", "Öklid algoritması"], a: "Eratosthenes yöntemi, 2'den başlayarak her asalın katlarını listeden siler. Geriye kalanlar asaldır." },
  { id: "p12-216", k: "Bilim", s: "11 ve 13 gibi aralarındaki fark 2 olan asal sayı çiftlerine ne denir?", d: "İkiz asallar", y: ["Mersenne asalları", "Mükemmel sayılar"], a: "3 ve 5, 5 ve 7, 17 ve 19 da ikiz asal çiftleridir." },
  { id: "p12-217", k: "Bilim", s: "\"2'den büyük her çift sayı iki asalın toplamıdır\" iddiası hangi adla bilinir?", d: "Goldbach sanısı", y: ["Fermat'nın son teoremi", "Riemann hipotezi"], a: "Christian Goldbach bu fikri 1742'de Euler'e yazdığı mektupta dile getirdi. Örneğin 10 = 3 + 7 = 5 + 5." },
  { id: "p12-218", k: "Bilim", s: "60 sayısının asal çarpanları hangileridir?", d: "2, 3 ve 5", y: ["2, 3 ve 7", "3, 4 ve 5"], a: "60 = 2 × 2 × 3 × 5'tir. 4 asal olmadığı için asal çarpan sayılmaz." },
  { id: "p12-219", k: "Bilim", s: "Kendisi hariç bölenlerinin toplamına eşit olan en küçük sayı (mükemmel sayı) kaçtır?", d: "6", y: ["8", "12"], a: "6'nın bölenleri 1, 2 ve 3'tür ve toplamları 6 eder." },
  { id: "p12-220", k: "Bilim", s: "6'dan sonra gelen ilk mükemmel sayı kaçtır?", d: "28", y: ["24", "36"], a: "28'in bölenleri 1, 2, 4, 7 ve 14'tür; toplamları 28 eder." },
  { id: "p12-221", k: "Bilim", s: "Bir üçgenin iç açılarının toplamı kaç derecedir?", d: "180°", y: ["360°", "90°"], a: "Düzlemdeki her üçgende iç açıların toplamı 180 derecedir." },
  { id: "p12-222", k: "Bilim", s: "Bir dörtgenin iç açılarının toplamı kaç derecedir?", d: "360°", y: ["180°", "540°"], a: "Dörtgen bir köşegenle iki üçgene ayrılabilir: 2 × 180 = 360 derece." },
  { id: "p12-223", k: "Bilim", s: "Bir beşgenin iç açılarının toplamı kaç derecedir?", d: "540°", y: ["360°", "720°"], a: "n kenarlı çokgende iç açılar toplamı (n - 2) × 180'dir. Beşgen için 3 × 180 = 540 derece." },
  { id: "p12-224", k: "Bilim", s: "Düzgün altıgenin her bir iç açısı kaç derecedir?", d: "120°", y: ["108°", "135°"], a: "Altıgenin iç açıları toplamı 720 derecedir. 720 / 6 = 120 derece eder." },
  { id: "p12-225", k: "Bilim", s: "Dik kenarları 3 cm ve 4 cm olan dik üçgenin hipotenüsü kaç cm'dir?", d: "5", y: ["6", "7"], a: "Pisagor teoremine göre 3² + 4² = 9 + 16 = 25 eder. 25'in karekökü 5'tir." },
  { id: "p12-226", k: "Bilim", s: "Dik üçgende hipotenüs hangi kenardır?", d: "Dik açının karşısındaki", y: ["En kısa kenar", "Tabana dik olan"], a: "Hipotenüs dik açının karşısındaki kenardır ve dik üçgenin en uzun kenarıdır." },
  { id: "p12-227", k: "Bilim", s: "Dik kenarları 5 ve 12 olan dik üçgenin hipotenüsü kaçtır?", d: "13", y: ["17", "15"], a: "5² + 12² = 25 + 144 = 169 eder. 169'un karekökü 13'tür." },
  { id: "p12-228", k: "Bilim", s: "Eşkenar üçgenin her bir iç açısı kaç derecedir?", d: "60°", y: ["45°", "90°"], a: "Eşkenar üçgenin üç açısı da eşittir: 180 / 3 = 60 derece." },
  { id: "p12-229", k: "Bilim", s: "90 dereceden büyük, 180 dereceden küçük açıya ne denir?", d: "Geniş açı", y: ["Dar açı", "Doğru açı"], a: "90 dereceden küçük açılar dar, tam 180 derece olan açı doğru açıdır." },
  { id: "p12-230", k: "Bilim", s: "Tam bir tur kaç derecedir?", d: "360°", y: ["180°", "400°"], a: "Bir tam dönüş 360 derecedir. Yarım tur ise 180 derece eder." },
  { id: "p12-231", k: "Bilim", s: "Arı peteklerindeki gözler hangi çokgen biçimindedir?", d: "Altıgen", y: ["Beşgen", "Kare"], a: "Düzgün altıgenler düzlemi boşluksuz kaplar ve aynı alanı daha az çevreyle çevreler. Bu da balmumundan tasarruf sağlar." },
  { id: "p12-232", k: "Bilim", s: "Bir küpün kaç yüzü vardır?", d: "6", y: ["8", "12"], a: "Küpün 6 kare yüzü, 12 ayrıtı ve 8 köşesi vardır." },
  { id: "p12-233", k: "Bilim", s: "Bir küpün kaç ayrıtı (kenarı) vardır?", d: "12", y: ["8", "6"], a: "Küpün üstte 4, altta 4 ve dikey 4 olmak üzere 12 ayrıtı vardır." },
  { id: "p12-234", k: "Bilim", s: "Euler'in formülüne göre dışbükey bir çokyüzlüde köşe - ayrıt + yüz sayısı kaçtır?", d: "2", y: ["0", "1"], a: "Küpte 8 - 12 + 6 = 2 eder. Bu eşitlik bütün dışbükey çokyüzlüler için geçerlidir." },
  { id: "p12-235", k: "Bilim", s: "Kaç tane düzgün dışbükey çokyüzlü (Platon cismi) vardır?", d: "5", y: ["7", "4"], a: "Dörtyüzlü, küp, sekizyüzlü, onikiyüzlü ve yirmiyüzlü. Başka düzgün dışbükey çokyüzlü yoktur." },
  { id: "p12-236", k: "Bilim", s: "Yirmi eşkenar üçgen yüzden oluşan Platon cismi hangisidir?", d: "İkosahedron", y: ["Dodekahedron", "Oktahedron"], a: "İkosahedron (yirmiyüzlü) 20 üçgen yüze sahiptir. Dodekahedronun 12 beşgen, oktahedronun 8 üçgen yüzü vardır." },
  { id: "p12-237", k: "Bilim", s: "Bir kenarı 4 cm olan karenin alanı kaç cm²'dir?", d: "16", y: ["8", "12"], a: "Karenin alanı kenarın karesidir: 4 × 4 = 16 cm²." },
  { id: "p12-238", k: "Bilim", s: "Bir ayrıtı 3 cm olan küpün hacmi kaç cm³'tür?", d: "27", y: ["9", "18"], a: "Küpün hacmi ayrıtın küpüdür: 3 × 3 × 3 = 27 cm³." },
  { id: "p12-239", k: "Bilim", s: "Kenarları 6 cm ve 4 cm olan dikdörtgenin çevresi kaç cm'dir?", d: "20", y: ["24", "10"], a: "Çevre = 2 × (6 + 4) = 20 cm. 24 ise dikdörtgenin alanıdır (cm²)." },
  { id: "p12-240", k: "Bilim", s: "Tabanı 10 cm, yüksekliği 6 cm olan üçgenin alanı kaç cm²'dir?", d: "30", y: ["60", "16"], a: "Üçgenin alanı taban × yükseklik / 2'dir: 10 × 6 / 2 = 30 cm²." },
  { id: "p12-241", k: "Bilim", s: "Yarıçapı r olan kürenin yüzey alanı hangi formülle bulunur?", d: "4πr²", y: ["2πr", "(4/3)πr³"], a: "Kürenin yüzey alanı 4πr²'dir. (4/3)πr³ ise kürenin hacmini verir." },
  { id: "p12-242", k: "Bilim", s: "Bir çemberin en uzun kirişi hangisidir?", d: "Çap", y: ["Yarıçap", "Teğet"], a: "Merkezden geçen kiriş çaptır ve çemberdeki en uzun kiriştir. Uzunluğu yarıçapın iki katıdır." },
  { id: "p12-243", k: "Bilim", s: "Bütün kenarları eşit ve bütün açıları dik olan dörtgen hangisidir?", d: "Kare", y: ["Eşkenar dörtgen", "Yamuk"], a: "Eşkenar dörtgenin de kenarları eşittir ama açıları dik olmak zorunda değildir." },
  { id: "p12-244", k: "Bilim", s: "1/2 + 1/4 işleminin sonucu kaçtır?", d: "3/4", y: ["2/6", "1/6"], a: "Paydaları eşitlersek 2/4 + 1/4 = 3/4 olur. Paylar ve paydalar ayrı ayrı toplanmaz." },
  { id: "p12-245", k: "Bilim", s: "3/4 kesri yüzde kaça eşittir?", d: "%75", y: ["%34", "%60"], a: "3/4 = 0,75 eder, bu da %75'tir." },
  { id: "p12-246", k: "Bilim", s: "0,2 ondalık sayısı hangi kesre eşittir?", d: "1/5", y: ["1/2", "2/5"], a: "0,2 = 2/10'dur; sadeleştirince 1/5 olur. 2/5 ise 0,4 eder." },
  { id: "p12-247", k: "Bilim", s: "30'un 2/3'ü kaçtır?", d: "20", y: ["15", "10"], a: "30'u 3'e bölersek 10 eder, 2 ile çarparsak 20 bulunur." },
  { id: "p12-248", k: "Bilim", s: "1/3 kesrinin ondalık yazılışı nedir?", d: "0,333…", y: ["0,13", "0,03"], a: "1/3, 3'lerin sonsuza dek tekrar ettiği devirli bir ondalık sayıdır." },
  { id: "p12-249", k: "Bilim", s: "1/8 kesrinin ondalık karşılığı nedir?", d: "0,125", y: ["0,18", "0,8"], a: "1'i 8'e bölünce 0,125 bulunur. Yani 1/8, %12,5'tir." },
  { id: "p12-250", k: "Bilim", s: "%25'i 40 olan sayı kaçtır?", d: "160", y: ["100", "10"], a: "%25 dörtte bir demektir. 40 dörtte birse sayının tamamı 4 × 40 = 160'tır." },
  { id: "p12-251", k: "Bilim", s: "200'ün %15'i kaçtır?", d: "30", y: ["15", "20"], a: "200'ün %10'u 20, %5'i 10'dur. Toplam 30 eder." },
  { id: "p12-252", k: "Bilim", s: "%20 indirimle 80 TL'ye satılan bir ürünün indirimsiz fiyatı kaç TL'dir?", d: "100", y: ["96", "120"], a: "80 TL, fiyatın %80'idir. 80 / 0,8 = 100 TL. %20 ekleyip 96 bulmak yaygın bir hatadır." },
  { id: "p12-253", k: "Bilim", s: "3/4, 2/3 ve 5/8 kesirlerinden hangisi en büyüktür?", d: "3/4", y: ["2/3", "5/8"], a: "3/4 = 0,75; 2/3 ≈ 0,67; 5/8 = 0,625'tir." },
  { id: "p12-254", k: "Bilim", s: "Hileli olmayan bir zar atıldığında 6 gelme olasılığı nedir?", d: "1/6", y: ["1/2", "1/3"], a: "Zarın altı yüzü eşit şansa sahiptir. Bu yüzden her sayının gelme olasılığı 1/6'dır." },
  { id: "p12-255", k: "Bilim", s: "Bir madeni para iki kez atılınca iki kez de yazı gelme olasılığı nedir?", d: "1/4", y: ["1/2", "1/3"], a: "Her atışta yazı olasılığı 1/2'dir. İki bağımsız atış için 1/2 × 1/2 = 1/4 eder." },
  { id: "p12-256", k: "Bilim", s: "İki zar birlikte atıldığında en sık gelmesi beklenen toplam kaçtır?", d: "7", y: ["6", "12"], a: "Toplam 7, 36 olası sonucun 6'sında çıkar (1+6, 2+5, 3+4 ve tersleri). Başka hiçbir toplam bu kadar sık değildir." },
  { id: "p12-257", k: "Bilim", s: "İki zar atıldığında toplamın 12 gelme olasılığı nedir?", d: "1/36", y: ["1/12", "1/6"], a: "12 için iki zarın da 6 gelmesi gerekir: 1/6 × 1/6 = 1/36." },
  { id: "p12-258", k: "Bilim", s: "52'lik iskambil destesinden rastgele çekilen kartın as olma olasılığı nedir?", d: "1/13", y: ["1/4", "1/52"], a: "Destede 4 as vardır: 4/52 = 1/13." },
  { id: "p12-259", k: "Bilim", s: "Bir grupta iki kişinin doğum gününün aynı olma olasılığı en az kaç kişiyle %50'yi geçer?", d: "23", y: ["183", "365"], a: "\"Doğum günü problemi\" denen bu sonuç şaşırtıcıdır: 23 kişide olasılık yaklaşık %50,7'dir." },
  { id: "p12-260", k: "Bilim", s: "Bir olayın olasılığı hangi iki değer arasındadır?", d: "0 ile 1", y: ["-1 ile 1", "1 ile 10"], a: "Olasılığı 0 olan olay imkânsız, 1 olan olay kesindir." },
  { id: "p12-261", k: "Bilim", s: "Monty Hall probleminde kapı değiştiren yarışmacının kazanma olasılığı nedir?", d: "2/3", y: ["1/2", "1/3"], a: "İlk seçim 1/3 olasılıkla doğrudur. Sunucu boş bir kapıyı açınca kalan 2/3'lük şans diğer kapıya geçer." },
  { id: "p12-262", k: "Bilim", s: "1654'te mektuplaşarak olasılık kuramının temellerini atan iki matematikçi kimlerdir?", d: "Pascal ve Fermat", y: ["Newton ve Leibniz", "Euler ve Gauss"], a: "Pascal ve Fermat, yarıda kalan bir şans oyununda ödülün nasıl paylaşılacağını tartışırken bu kuramı geliştirdi." },
  { id: "p12-263", k: "Bilim", s: "5! (5 faktöriyel) kaçtır?", d: "120", y: ["25", "60"], a: "5! = 5 × 4 × 3 × 2 × 1 = 120." },
  { id: "p12-264", k: "Bilim", s: "0! (sıfır faktöriyel) kaçtır?", d: "1", y: ["0", "Tanımsız"], a: "Tanım gereği 0! = 1'dir. Hiç nesne olmayan bir küme tek bir şekilde sıralanır." },
  { id: "p12-265", k: "Bilim", s: "Üç farklı kitap bir rafa kaç farklı şekilde dizilebilir?", d: "6", y: ["3", "9"], a: "İlk yere 3, ikinciye 2, üçüncüye 1 kitap konabilir: 3 × 2 × 1 = 6." },
  { id: "p12-266", k: "Bilim", s: "1, 1, 2, 3, 5, 8 diye giden Fibonacci dizisinde sıradaki sayı nedir?", d: "13", y: ["11", "12"], a: "Fibonacci dizisinde her sayı kendinden önceki iki sayının toplamıdır: 5 + 8 = 13." },
  { id: "p12-267", k: "Bilim", s: "Fibonacci diye tanınan Orta Çağ matematikçisi hangi şehirlidir?", d: "Pisa", y: ["Floransa", "Venedik"], a: "Pisalı Leonardo, 1202'de yazdığı Liber Abaci ile Hint-Arap rakamlarını Avrupa'da yaygınlaştırdı." },
  { id: "p12-268", k: "Bilim", s: "Altın oranın yaklaşık değeri nedir?", d: "1,618", y: ["1,414", "2,718"], a: "Altın oran (1 + √5) / 2'ye eşittir. 1,414 √2'nin, 2,718 ise e sayısının yaklaşık değeridir." },
  { id: "p12-269", k: "Bilim", s: "√2'nin (iki karekök) yaklaşık değeri nedir?", d: "1,414", y: ["1,732", "1,5"], a: "1,414 × 1,414 yaklaşık 2 eder. 1,732 ise √3'ün yaklaşık değeridir." },
  { id: "p12-270", k: "Bilim", s: "Doğal logaritmanın tabanı olan e sayısının yaklaşık değeri nedir?", d: "2,718", y: ["3,141", "1,732"], a: "e sayısı da pi gibi irrasyoneldir. Bileşik faiz ve büyüme hesaplarında sıkça karşımıza çıkar." },
  { id: "p12-271", k: "Bilim", s: "Matematikteki e sayısı hangi matematikçinin adıyla anılır?", d: "Leonhard Euler", y: ["Carl Gauss", "Isaac Newton"], a: "e, \"Euler sayısı\" olarak da bilinir. Euler bu sabiti e harfiyle göstermeyi yaygınlaştırdı." },
  { id: "p12-272", k: "Bilim", s: "144'ün karekökü kaçtır?", d: "12", y: ["14", "11"], a: "12 × 12 = 144 eder." },
  { id: "p12-273", k: "Bilim", s: "2'nin 10. kuvveti kaçtır?", d: "1024", y: ["1000", "2048"], a: "2¹⁰ = 1024'tür. Bilgisayarda 1 kilobaytın eskiden 1024 bayt kabul edilmesi buradan gelir." },
  { id: "p12-274", k: "Bilim", s: "13 × 13 kaçtır?", d: "169", y: ["156", "196"], a: "13 × 13 = 169. 196 ise 14'ün karesidir." },
  { id: "p12-275", k: "Bilim", s: "25 × 25 kaçtır?", d: "625", y: ["525", "650"], a: "25 × 25 = 625. Pratik yol: 5 ile biten sayının karesi için 2 × 3 = 6 yazılır, sonuna 25 eklenir." },
  { id: "p12-276", k: "Bilim", s: "7 × 8 kaçtır?", d: "56", y: ["54", "63"], a: "7 × 8 = 56. Akılda tutmanın yolu: 5, 6, 7, 8 → 56 = 7 × 8." },
  { id: "p12-277", k: "Bilim", s: "1'den 100'e kadar olan tam sayıların toplamı kaçtır?", d: "5050", y: ["5000", "10100"], a: "Rivayete göre Gauss bunu çocukken buldu: 1+100, 2+99… her çift 101 eder ve 50 çift vardır. 50 × 101 = 5050." },
  { id: "p12-278", k: "Bilim", s: "15'in karesi kaçtır?", d: "225", y: ["215", "250"], a: "15 × 15 = 225. 1 × 2 = 2 yazılıp sonuna 25 eklenerek de bulunabilir." },
  { id: "p12-279", k: "Bilim", s: "1000'in 8'e bölümü kaçtır?", d: "125", y: ["120", "150"], a: "8 × 125 = 1000 eder. Yani 1/8 = 0,125'tir." },
  { id: "p12-280", k: "Bilim", s: "999 + 999 kaçtır?", d: "1998", y: ["1898", "1988"], a: "Kolay yol: 1000 + 1000 = 2000, sonra 2 çıkarılır: 1998." },
  { id: "p12-281", k: "Bilim", s: "12 × 15 kaçtır?", d: "180", y: ["170", "160"], a: "12 × 15 = 12 × 10 + 12 × 5 = 120 + 60 = 180." },
  { id: "p12-282", k: "Bilim", s: "12 düzineye (144 adet) ne ad verilir?", d: "Gros", y: ["Deste", "Kental"], a: "Bir düzine 12, bir gros ise 12 düzine yani 144 adettir." },
  { id: "p12-283", k: "Bilim", s: "Roma rakamlarında L hangi sayıyı gösterir?", d: "50", y: ["100", "500"], a: "Roma rakamlarında I=1, V=5, X=10, L=50, C=100, D=500 ve M=1000'dir." },
  { id: "p12-284", k: "Bilim", s: "Roma rakamlarıyla 1000 nasıl yazılır?", d: "M", y: ["D", "C"], a: "M 1000'i gösterir. D 500, C ise 100'dür." },
  { id: "p12-285", k: "Bilim", s: "Roma rakamıyla yazılan XIV hangi sayıdır?", d: "14", y: ["16", "9"], a: "X = 10, IV = 4 (5'ten 1 eksik). Toplam 14 eder." },
  { id: "p12-286", k: "Bilim", s: "Roma rakamıyla yazılan MMXXVI hangi yılı gösterir?", d: "2026", y: ["2016", "2024"], a: "MM = 2000, XX = 20, VI = 6. Toplam 2026 eder." },
  { id: "p12-287", k: "Bilim", s: "Roma rakamlarıyla 9 sayısı nasıl yazılır?", d: "IX", y: ["XI", "VIX"], a: "IX, 10'dan 1 eksik demektir. XI ise 10'a 1 eklenmiş hali, yani 11'dir." },
  { id: "p12-288", k: "Bilim", s: "İkili sayı sistemindeki 1010 sayısı onluk sistemde kaçtır?", d: "10", y: ["12", "8"], a: "1010 = 1×8 + 0×4 + 1×2 + 0×1 = 10." },
  { id: "p12-289", k: "Bilim", s: "Bilgisayarlar temelde hangi sayı sistemiyle çalışır?", d: "İkili sistem", y: ["Onluk sistem", "Altmışlık sistem"], a: "Bilgisayarlar her şeyi yalnızca 0 ve 1 rakamlarıyla, yani ikili sistemle işler." },
  { id: "p12-290", k: "Bilim", s: "Onluk sistemdeki 5 sayısı ikili sistemde nasıl yazılır?", d: "101", y: ["110", "111"], a: "5 = 4 + 1'dir: 1×4 + 0×2 + 1×1, yani 101. 110 altıya, 111 yediye eşittir." },
  { id: "p12-291", k: "Bilim", s: "On altılık (heksadesimal) sistemde A rakamı onluk sistemde kaçtır?", d: "10", y: ["11", "16"], a: "On altılık sistemde 0-9'dan sonra A=10, B=11, C=12, D=13, E=14, F=15 kullanılır." },
  { id: "p12-292", k: "Bilim", s: "Bir saatin 60 dakika olması hangi uygarlığın 60 tabanlı sayı sisteminden kalmadır?", d: "Babil", y: ["Roma", "Antik Yunan"], a: "Mezopotamya'da Sümerler ve Babilliler 60 tabanlı sayı sistemi kullanırdı. Saat ve açı ölçümü bu mirası taşır." },
  { id: "p12-293", k: "Bilim", s: "Sıfırı bir sayı olarak ele alıp onunla işlem kuralları yazan 7. yüzyıl Hint matematikçisi kimdir?", d: "Brahmagupta", y: ["Harezmi", "Fibonacci"], a: "Brahmagupta 628'de yazdığı eserde sıfırla toplama, çıkarma ve çarpma kurallarını tanımladı." },
  { id: "p12-294", k: "Bilim", s: "\"Algoritma\" kelimesi hangi bilginin adından türemiştir?", d: "Harezmi", y: ["Ömer Hayyam", "İbn Sina"], a: "Harezmi'nin adı Latinceye \"Algoritmi\" diye geçti ve zamanla \"algoritma\" kelimesine dönüştü." },
  { id: "p12-295", k: "Bilim", s: "Geometrinin temel eseri sayılan \"Elemanlar\" kitabının yazarı kimdir?", d: "Öklid", y: ["Arşimet", "Pisagor"], a: "Öklid'in Elemanlar'ı yaklaşık 2.000 yıl boyunca geometri öğretiminde temel kitap olarak kullanıldı." },
  { id: "p12-296", k: "Bilim", s: "Fermat'nın Son Teoremi'ni 1994'te kanıtlayan matematikçi kimdir?", d: "Andrew Wiles", y: ["Grigori Perelman", "Terence Tao"], a: "Fermat bu iddiayı 1637'de bir kitabın kenarına yazmıştı. Kanıt 350 yılı aşkın süre sonra Wiles'tan geldi." },
  { id: "p12-297", k: "Bilim", s: "Poincaré sanısını kanıtlayıp Fields Madalyası'nı reddeden matematikçi kimdir?", d: "Grigori Perelman", y: ["Andrew Wiles", "John Nash"], a: "Rus matematikçi Perelman 2006'da Fields Madalyası'nı, 2010'da da 1 milyon dolarlık Milenyum Ödülü'nü reddetti." },
  { id: "p12-298", k: "Bilim", s: "Bir dairenin çapı 10 cm ise yarıçapı kaç cm'dir?", d: "5", y: ["20", "3,14"], a: "Yarıçap çapın yarısıdır: 10 / 2 = 5 cm." },
  { id: "p12-299", k: "Bilim", s: "π = 3,14 alınırsa çapı 10 cm olan çemberin çevresi kaç cm olur?", d: "31,4", y: ["78,5", "15,7"], a: "Çevre = π × çap = 3,14 × 10 = 31,4 cm. 78,5 ise bu dairenin alanıdır (cm²)." },
  { id: "p12-300", k: "Bilim", s: "Düzgün beşgenin her bir iç açısı kaç derecedir?", d: "108°", y: ["120°", "90°"], a: "Beşgenin iç açıları toplamı 540 derecedir. 540 / 5 = 108 derece eder." },
  { id: "p12-301", k: "Bilim", s: "Pisagor hangi Ege adasında doğmuştur?", d: "Sisam", y: ["Girit", "Rodos"], a: "Pisagor MÖ 6. yüzyılda Sisam (Samos) adasında doğdu. Daha sonra güney İtalya'daki Kroton'da okulunu kurdu." },
  { id: "p12-302", k: "Bilim", s: "İlk Yunan matematikçi ve filozoflarından Thales hangi kentlidir?", d: "Milet", y: ["Efes", "Atina"], a: "Thales, bugün Aydın sınırlarındaki antik Milet kentinde yaşadı. Adını taşıyan geometri teoremleriyle tanınır." },
  { id: "p12-303", k: "Bilim", s: "Antik İskenderiye'de yaşamış ünlü kadın matematikçi ve filozof kimdir?", d: "Hipatya", y: ["Kleopatra", "Aspasia"], a: "Hipatya 4. ve 5. yüzyıllarda İskenderiye'de matematik ve felsefe öğretti. Tarihte adı bilinen ilk kadın matematikçilerdendir." },
  { id: "p12-304", k: "Bilim", s: "Rubaileriyle tanınan ve kübik denklemler üzerine çalışan İranlı matematikçi kimdir?", d: "Ömer Hayyam", y: ["Biruni", "İbn Sina"], a: "Ömer Hayyam şair olduğu kadar matematikçi ve astronomdu. Kübik denklemleri geometrik yollarla çözdü." },
  { id: "p12-305", k: "Bilim", s: "Portresi 10 TL banknotlarda yer alan Türk matematikçi kimdir?", d: "Cahit Arf", y: ["Ali Kuşçu", "Kerim Erim"], a: "Cahit Arf'ın adını taşıyan \"Arf değişmezi\" matematikte bugün de kullanılır. Portresi 2009'dan beri 10 TL'nin arkasındadır." },
  { id: "p12-306", k: "Bilim", s: "Newton ve Leibniz'in birbirinden bağımsız geliştirdiği matematik dalı hangisidir?", d: "Kalkülüs", y: ["Olasılık", "Trigonometri"], a: "Diferansiyel ve integral hesap 17. yüzyılın sonunda ikisi tarafından ayrı ayrı geliştirildi. Kimin önce bulduğu uzun süre tartışıldı." },
  { id: "p12-307", k: "Bilim", s: "x-y koordinat sistemine adı verilen (\"Kartezyen\") matematikçi kimdir?", d: "René Descartes", y: ["Blaise Pascal", "Pierre de Fermat"], a: "Kartezyen sözcüğü Descartes'ın Latince adı Cartesius'tan gelir. Bu sistem cebir ile geometriyi birleştirdi." },
  { id: "p12-308", k: "Bilim", s: "Logaritmayı 1614'te yayımladığı eserle tanıtan matematikçi kimdir?", d: "John Napier", y: ["Isaac Newton", "Leonhard Euler"], a: "İskoç matematikçi Napier'in logaritması, büyük çarpma işlemlerini toplamaya indirgeyerek hesapları çok hızlandırdı." },
  { id: "p12-309", k: "Bilim", s: "\"Matematikçilerin prensi\" lakabıyla anılan Alman matematikçi kimdir?", d: "Carl Friedrich Gauss", y: ["Gottfried Leibniz", "Bernhard Riemann"], a: "Gauss sayılar kuramından istatistiğe pek çok alanda temel katkılar yaptı. Normal dağılım eğrisi \"Gauss eğrisi\" diye de bilinir." },
  { id: "p12-310", k: "Bilim", s: "İlk bilgisayar programını yazan kişi olarak anılan matematikçi kimdir?", d: "Ada Lovelace", y: ["Grace Hopper", "Marie Curie"], a: "Ada Lovelace 1843'te Babbage'ın Analitik Makinesi için bir algoritma yayımladı. Bu, ilk bilgisayar programı olarak kabul edilir." },
  { id: "p12-311", k: "Bilim", s: "II. Dünya Savaşı'nda Enigma şifresinin çözülmesine katkı veren İngiliz matematikçi kimdir?", d: "Alan Turing", y: ["John von Neumann", "Charles Babbage"], a: "Turing, bilgisayar biliminin kurucularından sayılır. Bilişimin en prestijli ödülü olan Turing Ödülü onun adını taşır." },
  { id: "p12-312", k: "Bilim", s: "Matematikte 40 yaş altı araştırmacılara dört yılda bir verilen ünlü ödül hangisidir?", d: "Fields Madalyası", y: ["Abel Ödülü", "Wolf Ödülü"], a: "Fields Madalyası Uluslararası Matematik Kongresi'nde verilir ve sıkça \"matematiğin Nobel'i\" diye anılır." },
  { id: "p12-313", k: "Bilim", s: "Fields Madalyası'nı kazanan ilk kadın kimdir?", d: "Meryem Mirzahani", y: ["Emmy Noether", "Sofya Kovalevskaya"], a: "İranlı matematikçi Meryem Mirzahani bu ödülü 2014'te, eğri yüzeylerin geometrisi üzerine çalışmalarıyla kazandı." },
  { id: "p12-314", k: "Bilim", s: "Pascal üçgeninde her sayı nasıl elde edilir?", d: "Üstteki iki sayının toplamıyla", y: ["Üstteki iki sayının çarpımıyla", "Üstteki iki sayının farkıyla"], a: "Kenarlar 1'lerden oluşur, içteki her sayı hemen üstündeki iki sayının toplamıdır. Örneğin 1, 2, 1'in altında 1, 3, 3, 1 gelir." },
  { id: "p12-315", k: "Bilim", s: "\"Pascaline\" adlı mekanik hesap makinesini yapan bilim insanı kimdir?", d: "Blaise Pascal", y: ["Isaac Newton", "René Descartes"], a: "Pascal bu makineyi 1640'larda vergi memuru babasının hesaplarını kolaylaştırmak için geliştirdi." },
  { id: "p12-316", k: "Bilim", s: "Abaküs nedir?", d: "Boncuklu hesap aracı", y: ["Geometri çizim aleti", "Açı ölçer"], a: "Abaküs, tellere dizili boncuklarla toplama ve çıkarma yapmaya yarayan çok eski bir hesap aracıdır." },
  { id: "p12-317", k: "Bilim", s: "Bir şeridin ucunu yarım tur çevirip yapıştırarak elde edilen Möbius şeridinin kaç yüzü vardır?", d: "1", y: ["2", "3"], a: "Möbius şeridinin üzerinde parmağınızı kaldırmadan gezerseniz her iki tarafa da ulaşırsınız. Yani tek yüzü vardır." },
  { id: "p12-318", k: "Bilim", s: "Matematikte ∞ sembolü neyi gösterir?", d: "Sonsuzluk", y: ["Yaklaşık eşitlik", "Toplam"], a: "Sonsuzluk sembolünü 1655'te İngiliz matematikçi John Wallis kullanmaya başladı." },
  { id: "p12-319", k: "Bilim", s: "Matematikte büyük Yunan harfi Σ (sigma) genellikle neyi gösterir?", d: "Toplamı", y: ["Çarpımı", "Farkı"], a: "Σ, bir dizi terimin toplanacağını belirtir. Çarpım için ise büyük pi harfi (Π) kullanılır." },
  { id: "p12-320", k: "Bilim", s: "1'in ardından 100 sıfır gelen sayıya ne ad verilir?", d: "Googol", y: ["Katrilyon", "Trilyon"], a: "Googol adını 1930'larda 9 yaşındaki bir çocuk önerdi. Google şirketinin adı da bu sözcükten esinlenmiştir." },
  { id: "p12-321", k: "Bilim", s: "Bir milyar yazılırken kaç sıfır kullanılır?", d: "9", y: ["6", "12"], a: "Bir milyar 1.000.000.000'dur. Bir milyonda 6, bir trilyonda 12 sıfır vardır." },
  { id: "p12-322", k: "Bilim", s: "Bir çift sayı ile bir tek sayının toplamı nasıl bir sayıdır?", d: "Tek", y: ["Çift", "Asal"], a: "Örneğin 4 + 3 = 7, 10 + 5 = 15. Çift ile tek sayının toplamı her zaman tektir." },
  { id: "p12-323", k: "Bilim", s: "İki tek sayının çarpımı nasıl bir sayıdır?", d: "Tek", y: ["Çift", "Asal"], a: "Örneğin 3 × 5 = 15, 7 × 9 = 63. İki tek sayının çarpımı her zaman tektir." },
  { id: "p12-324", k: "Bilim", s: "Sıfır tek sayı mıdır, çift sayı mı?", d: "Çift", y: ["Tek", "Hem tek hem çift"], a: "Sıfır 2'ye kalansız bölünür (0 / 2 = 0). Bu yüzden çift sayıdır." },
  { id: "p12-325", k: "Bilim", s: "İki negatif sayının çarpımı nasıl bir sayıdır?", d: "Pozitif", y: ["Negatif", "Sıfır"], a: "Örneğin (-3) × (-4) = 12'dir. Eksi ile eksinin çarpımı artıdır." },
  { id: "p12-326", k: "Bilim", s: "Sıfırdan farklı bir sayının sıfıra bölümü nedir?", d: "Tanımsız", y: ["Sıfır", "Bir"], a: "Hiçbir sayı sıfırla çarpılınca 5 gibi sıfırdan farklı bir sonuç vermez. Bu yüzden sıfıra bölme tanımsızdır." },
  { id: "p12-327", k: "Bilim", s: "Bir sayının 3'e tam bölünüp bölünmediği nasıl anlaşılır?", d: "Rakamları toplamına bakılır", y: ["Son rakamına bakılır", "Basamak sayısına bakılır"], a: "Rakamlarının toplamı 3'ün katıysa sayı 3'e bölünür. Örneğin 123: 1 + 2 + 3 = 6." },
  { id: "p12-328", k: "Bilim", s: "Bir sayının 5'e tam bölünmesi için son rakamı ne olmalıdır?", d: "0 ya da 5", y: ["Yalnız 5", "Çift bir rakam"], a: "Son rakamı 0 ya da 5 olan her tam sayı 5'e kalansız bölünür." },
  { id: "p12-329", k: "Bilim", s: "1 ile 100 arasında kaç asal sayı vardır?", d: "25", y: ["20", "30"], a: "2'den 97'ye kadar 25 asal sayı vardır." },
  { id: "p12-330", k: "Bilim", s: "1 ve kendisi dışında da böleni olan doğal sayılara ne denir?", d: "Bileşik sayı", y: ["Asal sayı", "İrrasyonel sayı"], a: "4, 6, 8, 9 gibi sayılar bileşiktir. 1 ise ne asal ne de bileşik sayılır." },
  { id: "p12-331", k: "Bilim", s: "72, 81 ve 90 sayılarından hangisi bir tam karedir?", d: "81", y: ["72", "90"], a: "81 = 9 × 9'dur. 72 ve 90 hiçbir tam sayının karesi değildir." },
  { id: "p12-332", k: "Bilim", s: "2, 4, 8, 16 diye giden dizide sıradaki sayı nedir?", d: "32", y: ["24", "20"], a: "Her terim bir öncekinin iki katıdır: 16 × 2 = 32." },
  { id: "p12-333", k: "Bilim", s: "1, 3, 6, 10 diye giden üçgensel sayılar dizisinde sıradaki sayı nedir?", d: "15", y: ["14", "16"], a: "Fark her adımda bir artar: +2, +3, +4, +5. 10 + 5 = 15 eder." },
  { id: "p12-334", k: "Bilim", s: "12 ile 18'in en büyük ortak böleni (EBOB) kaçtır?", d: "6", y: ["3", "36"], a: "12'nin ve 18'in ortak bölenleri 1, 2, 3 ve 6'dır. En büyüğü 6'dır. 36 ise EKOK'tur." },
  { id: "p12-335", k: "Bilim", s: "4 ile 6'nın en küçük ortak katı (EKOK) kaçtır?", d: "12", y: ["24", "2"], a: "4'ün katları 4, 8, 12…; 6'nın katları 6, 12… İkisinin ortak en küçük katı 12'dir." },
  { id: "p12-336", k: "Bilim", s: "0,5 × 0,5 işleminin sonucu kaçtır?", d: "0,25", y: ["2,5", "1"], a: "Yarının yarısı çeyrektir: 0,5 × 0,5 = 0,25." },
  { id: "p12-337", k: "Bilim", s: "√81 + √49 işleminin sonucu kaçtır?", d: "16", y: ["12", "14"], a: "√81 = 9 ve √49 = 7'dir. Toplamları 16 eder." },
  { id: "p12-338", k: "Bilim", s: "3'ün küpü (3³) kaçtır?", d: "27", y: ["9", "81"], a: "3³ = 3 × 3 × 3 = 27. 9 karesi, 81 ise dördüncü kuvvetidir." },
  { id: "p12-339", k: "Bilim", s: "10⁻¹ (10 üzeri eksi 1) kaçtır?", d: "0,1", y: ["-10", "0,01"], a: "Negatif üs, sayının tersini alır: 10⁻¹ = 1/10 = 0,1." },
  { id: "p12-340", k: "Bilim", s: "Saatte 60 km hızla giden bir araç 2,5 saatte kaç km yol alır?", d: "150", y: ["120", "175"], a: "Yol = hız × zaman = 60 × 2,5 = 150 km." },
  { id: "p12-341", k: "Bilim", s: "Bir metrede kaç milimetre vardır?", d: "1000", y: ["100", "10"], a: "1 m = 100 cm ve 1 cm = 10 mm'dir. Yani 1 m = 1000 mm." },
  { id: "p12-342", k: "Bilim", s: "Bir litre kaç santimetreküptür?", d: "1000", y: ["100", "10.000"], a: "1 litre, 10 cm × 10 cm × 10 cm'lik bir küpün hacmine, yani 1000 cm³'e eşittir." },
  { id: "p12-343", k: "Bilim", s: "Bir hektar kaç metrekaredir?", d: "10.000", y: ["1000", "100.000"], a: "1 hektar, kenarı 100 m olan karenin alanıdır: 100 × 100 = 10.000 m²." },
  { id: "p12-344", k: "Bilim", s: "Türkiye'de kullanılan bir dönüm kaç metrekaredir?", d: "1000", y: ["500", "10.000"], a: "Günümüzde Türkiye'de 1 dönüm 1000 m² kabul edilir. 10 dönüm 1 hektar eder." },
  { id: "p12-345", k: "Bilim", s: "Sıfırdan büyük hangi sayının hem karesi hem küpü kendisine eşittir?", d: "1", y: ["2", "10"], a: "1² = 1 ve 1³ = 1'dir. 2'nin karesi 4, küpü 8'dir." },
  { id: "p12-346", k: "Bilim", s: "Bir çemberde 90 derecelik merkez açı, çemberin ne kadarını görür?", d: "Dörtte birini", y: ["Yarısını", "Üçte birini"], a: "Tam çember 360 derecedir: 90 / 360 = 1/4." },
  { id: "p12-347", k: "Bilim", s: "Bir karenin kaç simetri ekseni vardır?", d: "4", y: ["2", "8"], a: "Karenin iki köşegeni ve karşılıklı kenarların ortalarını birleştiren iki doğru, toplam 4 simetri ekseni oluşturur." },
  { id: "p12-348", k: "Bilim", s: "Bir eşkenar üçgenin kaç simetri ekseni vardır?", d: "3", y: ["1", "6"], a: "Her köşeden karşı kenarın ortasına inen doğru bir simetri eksenidir. Toplam 3 tane vardır." },
  { id: "p12-349", k: "Bilim", s: "Bir dairenin kaç simetri ekseni vardır?", d: "Sonsuz sayıda", y: ["4", "360"], a: "Merkezden geçen her doğru daireyi iki eş parçaya böler. Bu yüzden sonsuz sayıda simetri ekseni vardır." },
  { id: "p12-350", k: "Bilim", s: "Bir üçgen prizmanın kaç yüzü vardır?", d: "5", y: ["6", "3"], a: "Üçgen prizmanın 2 üçgen tabanı ve 3 dikdörtgen yan yüzü vardır: toplam 5." },
  { id: "p12-351", k: "Bilim", s: "Taban yarıçapı r, yüksekliği h olan silindirin hacmi hangi formülle bulunur?", d: "πr²h", y: ["2πrh", "(1/3)πr²h"], a: "Silindirin hacmi taban alanı × yüksekliktir. (1/3)πr²h ise koninin hacmini verir." },
  { id: "p12-352", k: "Bilim", s: "Tabanı ve yüksekliği aynı olan bir koninin hacmi, silindirin hacminin ne kadarıdır?", d: "Üçte biri", y: ["Yarısı", "Dörtte biri"], a: "Koninin hacmi aynı taban ve yükseklikteki silindirin tam üçte biridir." },
  { id: "p12-353", k: "Bilim", s: "Bir beşgenin kaç köşegeni vardır?", d: "5", y: ["10", "3"], a: "n kenarlı çokgenin köşegen sayısı n × (n - 3) / 2'dir. Beşgen için 5 × 2 / 2 = 5." },
  { id: "p12-354", k: "Bilim", s: "Bir üçgende en uzun kenarın karşısında hangi açı bulunur?", d: "En büyük açı", y: ["En küçük açı", "Her zaman dik açı"], a: "Üçgende büyük kenarın karşısında büyük açı, küçük kenarın karşısında küçük açı bulunur." },
  { id: "p12-355", k: "Bilim", s: "Rasyonel sayılar kümesi hangi harfle gösterilir?", d: "Q", y: ["R", "Z"], a: "Q, İtalyanca \"bölüm\" anlamındaki quoziente'den gelir. R gerçek sayıları, Z tam sayıları gösterir." },
  { id: "p12-356", k: "Bilim", s: "Sanal birim i'nin karesi (i²) kaçtır?", d: "-1", y: ["1", "0"], a: "i, karesi -1 olan sayı olarak tanımlanır. Karmaşık sayılar bu tanım üzerine kuruludur." },
  { id: "p12-357", k: "Bilim", s: "Euler özdeşliğine göre e^(iπ) + 1 kaça eşittir?", d: "0", y: ["1", "-1"], a: "e^(iπ) = -1'dir, bu yüzden e^(iπ) + 1 = 0 olur. Bu eşitlik e, i, π, 1 ve 0'ı tek satırda buluşturur." },
  { id: "p12-358", k: "Bilim", s: "Matematikte doğruluğu kanıtlanmış önermeye ne ad verilir?", d: "Teorem", y: ["Sanı", "Tanım"], a: "Teorem, mantıksal adımlarla kanıtlanmış önermedir. Pisagor teoremi en bilinen örneklerdendir." },
  { id: "p12-359", k: "Bilim", s: "Doğru olduğu düşünülen ama henüz kanıtlanmamış matematiksel önermeye ne denir?", d: "Sanı", y: ["Teorem", "Formül"], a: "Sanı (konjektür), kanıtlanınca teorem olur. Fermat'nın son teoremi de uzun süre aslında bir sanıydı." },
  { id: "p12-360", k: "Bilim", s: "Kanıtlanmadan doğru kabul edilen temel önermeye ne denir?", d: "Aksiyom", y: ["Teorem", "Sonuç"], a: "Aksiyomlar bir matematik sisteminin başlangıç taşlarıdır. Öklid geometrisi beş temel önermeye dayanır." },
  { id: "p12-361", k: "Bilim", s: "Fatih Sultan Mehmet döneminde İstanbul'da ders veren ünlü astronom ve matematikçi kimdir?", d: "Ali Kuşçu", y: ["Takiyüddin", "Piri Reis"], a: "Ali Kuşçu Semerkant'ta Uluğ Bey'in yanında yetişti. İstanbul'a gelince Ayasofya Medresesi'nde ders verdi." },
  { id: "p12-362", k: "Bilim", s: "Bir milyonun karekökü kaçtır?", d: "1000", y: ["100", "10.000"], a: "1000 × 1000 = 1.000.000 eder." },
  { id: "p12-363", k: "Bilim", s: "17 × 3 kaçtır?", d: "51", y: ["41", "54"], a: "17 × 3 = 51. Bu yüzden 51 asal değildir, sık yapılan bir yanılgıdır." },
  { id: "p12-364", k: "Bilim", s: "64'ün küpkökü kaçtır?", d: "4", y: ["8", "6"], a: "4 × 4 × 4 = 64'tür. 8 ise 64'ün kareköküdür." },
  { id: "p12-365", k: "Bilim", s: "48'in 0,5'e bölümü kaçtır?", d: "96", y: ["24", "48,5"], a: "0,5'e bölmek 2 ile çarpmakla aynıdır: 48 × 2 = 96." },
  { id: "p12-366", k: "Bilim", s: "2/5 + 1/5 işleminin sonucu kaçtır?", d: "3/5", y: ["3/10", "2/25"], a: "Paydalar eşit olduğunda yalnızca paylar toplanır: 2 + 1 = 3, payda 5 kalır." },
  { id: "p12-367", k: "Bilim", s: "Yarısının yarısı 10 olan sayı kaçtır?", d: "40", y: ["20", "5"], a: "Yarısının yarısı dörtte biridir. Dörtte biri 10 ise sayının tamamı 40'tır." },
  { id: "p12-368", k: "Bilim", s: "30 kişilik bir sınıfın %40'ı kız ise sınıfta kaç kız öğrenci vardır?", d: "12", y: ["10", "18"], a: "30'un %10'u 3'tür, %40'ı 4 × 3 = 12 eder. 18 ise erkek öğrenci sayısıdır." },
  { id: "p12-369", k: "Bilim", s: "Standart bir oyun zarında karşılıklı iki yüzün toplamı kaçtır?", d: "7", y: ["6", "8"], a: "Standart zarda 1'in karşısında 6, 2'nin karşısında 5, 3'ün karşısında 4 bulunur." },
  { id: "p12-370", k: "Bilim", s: "Saat tam 3'te akrep ile yelkovan arasındaki dar açı kaç derecedir?", d: "90°", y: ["30°", "45°"], a: "Kadranda her saat aralığı 360 / 12 = 30 derecedir. 3 aralık 90 derece eder." },
  { id: "p12-371", k: "Bilim", s: "Sayı doğrusunda -3 ile 5 arasındaki uzaklık kaç birimdir?", d: "8", y: ["2", "5"], a: "-3'ten 0'a 3 birim, 0'dan 5'e 5 birim vardır: 3 + 5 = 8." },
  { id: "p12-372", k: "Bilim", s: "4, 8 ve 12 sayılarının aritmetik ortalaması kaçtır?", d: "8", y: ["6", "12"], a: "Toplam 24'tür, 3 sayıya bölününce 8 eder." },
  { id: "p12-373", k: "Bilim", s: "3, 7, 9, 15, 20 sayılarının ortancası (medyanı) kaçtır?", d: "9", y: ["10,8", "7"], a: "Sıralı dizide tam ortadaki sayı ortancadır: 9. 10,8 ise bu sayıların aritmetik ortalamasıdır." },
  { id: "p12-374", k: "Bilim", s: "Bir düzinede kaç adet vardır?", d: "12", y: ["10", "20"], a: "Düzine 12 adet demektir. Yumurtaların düzineyle satılması bu yüzdendir." },
  { id: "p12-375", k: "Bilim", s: "Bir altıgenin kaç köşegeni vardır?", d: "9", y: ["6", "12"], a: "Köşegen sayısı n × (n - 3) / 2'dir. Altıgen için 6 × 3 / 2 = 9." },
  { id: "p12-376", k: "Bilim", s: "Bir sayı dizisinde sık tekrar eden değere istatistikte ne denir?", d: "Tepe değer (mod)", y: ["Ortanca", "Açıklık"], a: "Mod, veride en çok tekrar eden değerdir. Örneğin 2, 3, 3, 5 dizisinin modu 3'tür." },
  { id: "p12-377", k: "Bilim", s: "Bir dikdörtgenin köşegenleri için hangisi her zaman doğrudur?", d: "Uzunlukları eşittir", y: ["Birbirine diktir", "Kenarlara eşittir"], a: "Dikdörtgenin köşegenleri eşit uzunluktadır ve birbirini ortalar. Dik kesişmeleri yalnız karede görülür." },
  { id: "p12-378", k: "Bilim", s: "Kenarları 3 cm olan bir karenin köşegeni yaklaşık kaç cm'dir?", d: "4,24", y: ["6", "3,5"], a: "Karenin köşegeni kenar × √2'dir: 3 × 1,414 ≈ 4,24 cm." },
  { id: "p12-379", k: "Bilim", s: "Bir haftada kaç saat vardır?", d: "168", y: ["148", "186"], a: "7 gün × 24 saat = 168 saat." },
  { id: "p12-380", k: "Bilim", s: "Bir saatte kaç saniye vardır?", d: "3600", y: ["360", "6000"], a: "1 saat = 60 dakika, 1 dakika = 60 saniye: 60 × 60 = 3600 saniye." },
  { id: "p12-381", k: "Bilim", s: "Kireç taşının ana bileşeni olan kalsiyum karbonatın formülü nedir?", d: "CaCO3", y: ["CaO", "CaCl2"], a: "Kalsiyum karbonat bir kalsiyum, bir karbon ve üç oksijenden oluşur. CaO sönmemiş kireçtir." },
  { id: "p12-382", k: "Bilim", s: "Periyodik tablonun yaratıcısı Mendeleyev'in adı hangi elemente verilmiştir?", d: "Mendelevyum", y: ["Kopernikyum", "Bohriyum"], a: "Mendelevyum (Md) 1955'te yapay olarak üretildi. Kopernikyum Kopernik'in, bohriyum Niels Bohr'un adını taşır." },
  { id: "p12-383", k: "Bilim", s: "Dünyada en çok üretilen metal hangisidir?", d: "Demir", y: ["Alüminyum", "Bakır"], a: "Demir, çoğunlukla çelik halinde, açık ara en çok üretilen metaldir. Alüminyum ikinci sıradadır." },
  { id: "p12-384", k: "Bilim", s: "Gümüş eşyaların zamanla kararmasına ne yol açar?", d: "Havadaki kükürt bileşikleri", y: ["Havadaki azot", "Güneş ışığı"], a: "Gümüş, havadaki kükürtlü gazlarla tepkimeye girip siyahımsı gümüş sülfür tabakası oluşturur." },
  { id: "p12-385", k: "Bilim", s: "Galvanizli sacda demiri paslanmaya karşı korumak için hangi metal kaplanır?", d: "Çinko", y: ["Kalay", "Bakır"], a: "Çinko kaplama demirden önce tepkimeye girerek onu korur. Çizilse bile koruma bir süre devam eder." },
  { id: "p12-386", k: "Bilim", s: "Teneke konserve kutularında çeliğin üzeri hangi metalle kaplanır?", d: "Kalay", y: ["Çinko", "Kurşun"], a: "Teneke, ince bir kalay tabakasıyla kaplanmış çelik sactır. Kalay paslanmayı önler." },
  { id: "p12-387", k: "Bilim", s: "Mohs sertlik ölçeğinde en sert mineral olan 10 değerini hangisi alır?", d: "Elmas", y: ["Kuvars", "Korindon"], a: "Mohs ölçeğinde elmas 10, korindon 9, kuvars 7'dir. Elmas doğal mineraller arasında en serttir." },
  { id: "p12-388", k: "Bilim", s: "Mohs sertlik ölçeğinde en yumuşak mineral olan 1 değerini hangisi alır?", d: "Talk", y: ["Kalsit", "Kuvars"], a: "Talk tırnakla bile çizilebilir. Pudra yapımında kullanılır." },
  { id: "p12-389", k: "Bilim", s: "Etil alkol (etanol) yaklaşık kaç °C'de kaynar?", d: "78 °C", y: ["100 °C", "45 °C"], a: "Etanol yaklaşık 78 °C'de kaynar, yani sudan daha önce buharlaşır." },
  { id: "p12-390", k: "Bilim", s: "Şekerin ısıtılınca erimesi ve kahverengileşmesine ne denir?", d: "Karamelleşme", y: ["Sabunlaşma", "Süblimleşme"], a: "Karamelleşmede şeker molekülleri yüksek ısıyla parçalanıp yeni renk ve tat maddeleri oluşturur." },
  { id: "p12-391", k: "Bilim", s: "Kâğıdın yanması nasıl bir değişimdir?", d: "Kimyasal değişim", y: ["Fiziksel değişim", "Hal değişimi"], a: "Yanmada kâğıt kül, karbondioksit ve su buharı gibi yeni maddelere dönüşür ve geri elde edilemez." },
  { id: "p12-392", k: "Bilim", s: "Buzun erimesi nasıl bir değişimdir?", d: "Fiziksel değişim", y: ["Kimyasal değişim", "Çekirdek tepkimesi"], a: "Eriyen buz yine sudur, yalnız hali değişir. Yeni bir madde oluşmadığı için fiziksel değişimdir." },
  { id: "p12-393", k: "Bilim", s: "Hangisi homojen bir karışımdır?", d: "Tuzlu su", y: ["Kumlu su", "Zeytinyağlı su"], a: "Tuz suda tamamen çözünür ve karışımın her yeri aynı görünür. Kumlu ve yağlı su ise heterojendir." },
  { id: "p12-394", k: "Bilim", s: "Zeytinyağı ile su neden birbirine karışmaz?", d: "Su polar, yağ apolar", y: ["Yağ sudan ağır", "Su yağı mıknatıs gibi iter"], a: "Polar su molekülleri birbirini çeker ve apolar yağ moleküllerini dışarıda bırakır. Yağ sudan hafif olduğu için üstte toplanır." },
  { id: "p12-395", k: "Bilim", s: "Sabun yağlı kiri nasıl temizler?", d: "Hem suya hem yağa tutunur", y: ["Yağı buharlaştırır", "Kiri mıknatıs gibi çeker"], a: "Sabun molekülünün bir ucu suyu, diğer ucu yağı sever. Yağı sararak suyla birlikte uzaklaştırır." },
  { id: "p12-396", k: "Bilim", s: "Simyacılar değersiz metalleri hangi metale dönüştürmeye çalışırdı?", d: "Altın", y: ["Demir", "Bakır"], a: "Simyacılar kurşunu altına çevirmenin yolunu aradı. Başaramadılar ama deneyleri kimyanın gelişmesine katkı sağladı." },
  { id: "p12-397", k: "Bilim", s: "Elementlere bugün kullandığımız harf sembollerini veren İsveçli kimyager kimdir?", d: "Jöns Jacob Berzelius", y: ["Alfred Nobel", "Anders Celsius"], a: "Berzelius 1810'larda elementleri Latince adlarının baş harfleriyle göstermeyi önerdi. Fe, Au, Cu gibi semboller buradan gelir." },
  { id: "p12-398", k: "Bilim", s: "Hidrojeni 1766'da ayrı bir gaz olarak tanımlayan İngiliz bilim insanı kimdir?", d: "Henry Cavendish", y: ["Antoine Lavoisier", "John Dalton"], a: "Cavendish bu gaza \"yanıcı hava\" dedi. Hidrojen adını sonradan Lavoisier verdi; \"su oluşturan\" anlamına gelir." },
  { id: "p12-399", k: "Bilim", s: "Oksijeni 1774'te elde edip yayımlayan İngiliz kimyager kimdir?", d: "Joseph Priestley", y: ["Henry Cavendish", "Robert Boyle"], a: "Priestley oksijeni 1774'te yayımladı. İsveçli Carl Scheele de onu daha önce bağımsız olarak elde etmişti." },
  { id: "p12-400", k: "Bilim", s: "Kimyada \"Ar\" sembolü hangi elemente aittir?", d: "Argon", y: ["Arsenik", "Altın"], a: "Ar argonun sembolüdür. Arsenik As, altın ise Au ile gösterilir." },
];
